INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('SOCI.G7.POLITI.CITIZENSHIP.CZ_GLOBAL', 'SOCI.G7.POLITI.CITIZENSHIP.CZ_INTERDEP', 'skill', 'essential', 'This skill builds on it. Proposed, to confirm by a teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('SOCI.G7.POLITI.CITIZENSHIP.CZ_GLOBAL', 'SOCI.G6.RESOUR.COMMUNICATIO_N_IN_EASTER.CM_MODES', 'skill', 'helpful', 'Modern communication (Grade 6) is one force of globalisation. Proposed, to confirm by a CBC Social Studies teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('SOCI.G7.POLITI.CITIZENSHIP.CZ_CITIZEN', 'SOCI.G6.POLITI.CITIZENSHIP.CZ_QUALITIES', 'skill', 'essential', 'Grade 6 Social Studies taught it first. Proposed, to confirm by a teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('SOCI.G7.POLITI.CITIZENSHIP.CZ_CITIZEN', 'SOCI.G7.POLITI.CITIZENSHIP.CZ_GLOBAL', 'skill', 'essential', 'This skill builds on it. Proposed, to confirm by a teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.SOCIAL.SELF_EXPLORATION.SE_ABILITIES.M_SE_TALENT_ONLY', 'SOCI.G7.SOCIAL.SELF_EXPLORATION.SE_ABILITIES', 'Thinks only singing, sport or drawing count as abilities, so a quiet or practical strength is not one.', '{"question":"Which of these is an ability?","wrong_answer":"Only winning a prize","correct_answer":"Listening carefully to others"}'::jsonb, 'Schools praise prizes in sport, music and art, so the child thinks only visible, winning talents count.', 'Offer "Only winning a prize" next to the right answer and ask the question again in a new context.', 'Ask the child to name three things a classmate does well that are not on stage.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.SOCIAL.SELF_EXPLORATION.SE_ABILITIES.M_SE_INTEREST_ABILITY', 'SOCI.G7.SOCIAL.SELF_EXPLORATION.SE_ABILITIES', 'Says an interest and an ability are the same thing.', '{"question":"Amina likes football but has not played much. What is football for her?","wrong_answer":"An ability","correct_answer":"An interest"}'::jsonb, 'The child likes what they are good at, so liking and being able feel like the same thing.', 'Offer "An ability" next to the right answer and ask the question again in a new context.', 'Ask: can you like something you cannot yet do well?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.SOCIAL.SELF_EXPLORATION.SE_VALUES.M_SE_VALUES_THINGS', 'SOCI.G7.SOCIAL.SELF_EXPLORATION.SE_VALUES', 'Thinks a personal value is something a person owns, such as a phone or money.', '{"question":"Which is a personal value?","wrong_answer":"A new phone","correct_answer":"Honesty"}'::jsonb, 'The word "value" is used at home for what something costs, so the child reads it as worth in money.', 'Offer "A new phone" next to the right answer and ask the question again in a new context.', 'Ask the child what a person does when they find a lost wallet.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.SOCIAL.SELF_EXPLORATION.SE_VALUES.M_SE_VALUES_PEER', 'SOCI.G7.SOCIAL.SELF_EXPLORATION.SE_VALUES', 'Thinks a person should change their values to please friends.', '{"question":"Friends dare Kevin to copy in a test. What does a steady person do?","wrong_answer":"Copy to please them","correct_answer":"Say no and keep his values"}'::jsonb, 'Belonging to a group matters a great deal at this age, so pleasing friends feels more important than a value.', 'Offer "Copy to please them" next to the right answer and ask the question again in a new context.', 'Ask what happens to trust if Kevin copies once.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.SOCIAL.SELF_EXPLORATION.SE_EMOTIONS.M_SE_ANGER_BAD', 'SOCI.G7.SOCIAL.SELF_EXPLORATION.SE_EMOTIONS', 'Believes anger itself is wrong and must be hidden, instead of managed.', '{"question":"What is the best thing to do with anger?","wrong_answer":"Never feel it at all","correct_answer":"Calm down, then say what bothers you"}'::jsonb, 'Children are often told off for being angry, so they learn that the feeling itself is wrong.', 'Offer "Never feel it at all" next to the right answer and ask the question again in a new context.', 'Ask what Wanjiru does when she feels angry at a friend.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.SOCIAL.SELF_EXPLORATION.SE_EMOTIONS.M_SE_REVENGE', 'SOCI.G7.SOCIAL.SELF_EXPLORATION.SE_EMOTIONS', 'Picks hitting back or shouting as a way to manage anger.', '{"question":"Kamau is angry because a friend broke his pencil. What should he do?","wrong_answer":"Break his friend''s pencil too","correct_answer":"Breathe, then tell his friend what happened"}'::jsonb, 'Paying back feels fair, and the child has seen hitting back in films and at play.', 'Offer "Break his friend''s pencil too" next to the right answer and ask the question again in a new context.', 'Ask what happens to the friendship after the pencil is broken.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.SOCIAL.SELF_EXPLORATION.SE_ABILITIES.M_SE_FIXED_ABILITY', 'SOCI.G7.SOCIAL.SELF_EXPLORATION.SE_ABILITIES', 'Thinks abilities are fixed at birth and cannot grow with practice.', '{"question":"Wanjiku finds drawing hard. Can she get better at it?","wrong_answer":"No, you are born good or bad at it","correct_answer":"Yes, with practice and feedback"}'::jsonb, 'The child hears "she is talented" and not how much she practised.', 'Offer "No, you are born good or bad at it" next to the right answer and ask the question again in a new context.', 'Show early and later drawings by the same learner after practice.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.SOCIAL.SELF_EXPLORATION.SE_ABILITIES.M_SE_SKILL_TALENT', 'SOCI.G7.SOCIAL.SELF_EXPLORATION.SE_ABILITIES', 'Calls a skill learnt by practice, such as typing, a natural talent.', '{"question":"Otieno learnt to type fast after months of practice. Is typing a talent or a skill for him?","wrong_answer":"A talent","correct_answer":"A skill"}'::jsonb, 'Both words mean being good at something.', 'Offer "A talent" next to the right answer and ask the question again in a new context.', 'Sort: born with it (talent), learnt by practice (skill).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.SOCIAL.SELF_EXPLORATION.SE_VALUES.M_SE_VALUE_RULE', 'SOCI.G7.SOCIAL.SELF_EXPLORATION.SE_VALUES', 'Thinks a value is just a rule someone else makes.', '{"question":"Is honesty only a school rule?","wrong_answer":"Yes, it is a rule","correct_answer":"No, it is a personal value that guides what you do even without rules"}'::jsonb, 'Values and rules are taught side by side.', 'Offer "Yes, it is a rule" next to the right answer and ask the question again in a new context.', 'Ask whether you would tell the truth at home where the school rules do not apply.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.SOCIAL.SELF_EXPLORATION.SE_VALUES.M_SE_STEADY_STUBBORN', 'SOCI.G7.SOCIAL.SELF_EXPLORATION.SE_VALUES', 'Thinks a steady personality means never changing your mind even when wrong.', '{"question":"Juma learns he was wrong about a friend. What does a steady person do?","wrong_answer":"Never change his mind","correct_answer":"Admit the mistake and keep his values"}'::jsonb, 'Steady is mixed up with stubborn.', 'Offer "Never change his mind" next to the right answer and ask the question again in a new context.', 'Compare: changing values to please friends, and changing a mistaken idea.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.SOCIAL.SELF_EXPLORATION.SE_EMOTIONS.M_SE_HIDE_FOREVER', 'SOCI.G7.SOCIAL.SELF_EXPLORATION.SE_EMOTIONS', 'Thinks the healthy way with sadness is to hide it and tell nobody.', '{"question":"Achieng feels sad for many days. What is a healthy step?","wrong_answer":"Hide it and tell nobody","correct_answer":"Talk to a trusted adult or friend"}'::jsonb, 'The child has heard "be strong" and thinks sharing is weakness.', 'Offer "Hide it and tell nobody" next to the right answer and ask the question again in a new context.', 'Discuss who learners can talk to at school.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.SOCIAL.SELF_EXPLORATION.SE_EMOTIONS.M_SE_FEAR_ALWAYS_BAD', 'SOCI.G7.SOCIAL.SELF_EXPLORATION.SE_EMOTIONS', 'Thinks fear is always bad and has no use.', '{"question":"How can fear help a person?","wrong_answer":"It never helps","correct_answer":"It warns us of danger, such as a speeding car"}'::jsonb, 'The child hears fear spoken of as weakness.', 'Offer "It never helps" next to the right answer and ask the question again in a new context.', 'Ask what fear makes you do when a dog growls.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.SOCIAL.ENTREPRENEURIAL_OPPORTUN.EO_OPPORTUNITY.M_EO_CAPITAL_ONLY', 'SOCI.G7.SOCIAL.ENTREPRENEURIAL_OPPORTUN.EO_OPPORTUNITY', 'Thinks a business needs only money to begin, not a need, skills or a plan.', '{"question":"What does a good business idea need first?","wrong_answer":"A lot of money","correct_answer":"A need that people have"}'::jsonb, 'The child hears adults say "I would start a business if I had money", so money looks like the only need.', 'Offer "A lot of money" next to the right answer and ask the question again in a new context.', 'Ask: if nobody wants the product, can money save the business?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.SOCIAL.ENTREPRENEURIAL_OPPORTUN.EO_OPPORTUNITY.M_EO_SOCIAL_PROFIT', 'SOCI.G7.SOCIAL.ENTREPRENEURIAL_OPPORTUN.EO_OPPORTUNITY', 'Thinks a social entrepreneur only wants profit, or that they do not earn at all.', '{"question":"What does a social entrepreneur do?","wrong_answer":"Only makes the most profit","correct_answer":"Solves a community problem through a business"}'::jsonb, 'The child knows businesses make profit and charities give help, and does not see one that does both.', 'Offer "Only makes the most profit" next to the right answer and ask the question again in a new context.', 'Ask what a youth group that recycles plastic into bricks gains and gives.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.SOCIAL.ENTREPRENEURIAL_OPPORTUN.EO_OPPORTUNITY.M_EO_COPY_ANY', 'SOCI.G7.SOCIAL.ENTREPRENEURIAL_OPPORTUN.EO_OPPORTUNITY', 'Picks any popular business without matching it to their own personality or skills.', '{"question":"Baraka is shy but good with his hands. Which opportunity suits him best?","wrong_answer":"Selling loudly at a market","correct_answer":"Repairing shoes or bicycles"}'::jsonb, 'The child picks what others do.', 'Offer "Selling loudly at a market" next to the right answer and ask the question again in a new context.', 'Match three personalities to three opportunities.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.SOCIAL.ENTREPRENEURIAL_OPPORTUN.EO_OPPORTUNITY.M_EO_NO_CUSTOMER', 'SOCI.G7.SOCIAL.ENTREPRENEURIAL_OPPORTUN.EO_OPPORTUNITY', 'Plans a product without asking who will buy it.', '{"question":"Before making 100 bags of liquid soap, what should you find out?","wrong_answer":"Nothing, just make it","correct_answer":"Who will buy it and at what price"}'::jsonb, 'Making the product feels like the whole job.', 'Offer "Nothing, just make it" next to the right answer and ask the question again in a new context.', 'Ask what happens to soap no one buys.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.SOCIAL.ENTREPRENEURIAL_OPPORTUN.EO_OPPORTUNITY.M_EO_HONESTY_OPTIONAL', 'SOCI.G7.SOCIAL.ENTREPRENEURIAL_OPPORTUN.EO_OPPORTUNITY', 'Thinks honesty does not matter in business if you make a profit.', '{"question":"A trader mixes water into milk to sell more. Is this a good business idea?","wrong_answer":"Yes, more profit","correct_answer":"No, it cheats customers and loses their trust"}'::jsonb, 'Short-term profit looks like success.', 'Offer "Yes, more profit" next to the right answer and ask the question again in a new context.', 'Ask whether customers would come back.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.SOCIAL.ENTREPRENEURIAL_OPPORTUN.EO_OPPORTUNITY.M_EO_SOCIAL_CHARITY', 'SOCI.G7.SOCIAL.ENTREPRENEURIAL_OPPORTUN.EO_OPPORTUNITY', 'Thinks a social enterprise must give everything away free.', '{"question":"A group sells clean water cheaply to a village and earns a small income. Is it a social enterprise?","wrong_answer":"No, it charges money","correct_answer":"Yes, it solves a problem and earns income"}'::jsonb, 'The child thinks helping means free.', 'Offer "No, it charges money" next to the right answer and ask the question again in a new context.', 'Show how the income keeps the water project running.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.PEOPLE.HUMAN_ORIGIN.HO_TRADITIONAL.M_HO_SAME_STORY', 'SOCI.G7.PEOPLE.HUMAN_ORIGIN.HO_TRADITIONAL', 'Believes all African communities tell one and the same story of human origin.', '{"question":"Do all African communities tell the same story of how people began?","wrong_answer":"Yes, they all tell the same story","correct_answer":"No, each community has its own story"}'::jsonb, 'The child knows only their own community''s story and assumes others tell it too.', 'Offer "Yes, they all tell the same story" next to the right answer and ask the question again in a new context.', 'Ask the child to tell the story from their home community and compare it with a classmate.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.PEOPLE.HUMAN_ORIGIN.HO_TRADITIONAL.M_HO_STORY_FALSE', 'SOCI.G7.PEOPLE.HUMAN_ORIGIN.HO_TRADITIONAL', 'Calls a community''s story of origin a mere lie or fairy tale.', '{"question":"How should we treat the origin stories of other communities?","wrong_answer":"As silly stories that are not true","correct_answer":"With respect, as the beliefs of that community"}'::jsonb, 'The child hears stories called "myths" and takes the word to mean lies.', 'Offer "As silly stories that are not true" next to the right answer and ask the question again in a new context.', 'Ask how the child would feel if their own story were laughed at.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.PEOPLE.HUMAN_ORIGIN.HO_RELIGIOUS.M_HO_ADAM_ONLY', 'SOCI.G7.PEOPLE.HUMAN_ORIGIN.HO_RELIGIOUS', 'Thinks only one faith has a story of how people began.', '{"question":"Which religions tell a story about how people began?","wrong_answer":"Only Christianity","correct_answer":"Christianity and Islam both do"}'::jsonb, 'The child knows the story from their own faith and has not heard the other faith''s version.', 'Offer "Only Christianity" next to the right answer and ask the question again in a new context.', 'Ask the child what Adam is called in the Bible and in the Qur''an.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.PEOPLE.HUMAN_ORIGIN.HO_RELIGIOUS.M_HO_NO_COMMON', 'SOCI.G7.PEOPLE.HUMAN_ORIGIN.HO_RELIGIOUS', 'Says traditional and religious stories have nothing in common.', '{"question":"What do traditional and religious stories of human origin share?","wrong_answer":"Nothing at all","correct_answer":"A creator and a first man and woman"}'::jsonb, 'The stories come from different peoples, so the child expects them to be completely different.', 'Offer "Nothing at all" next to the right answer and ask the question again in a new context.', 'Ask the child to list who made people, and who the first people were, in two stories.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.PEOPLE.HUMAN_ORIGIN.HO_TRADITIONAL.M_HO_WRITTEN_FIRST', 'SOCI.G7.PEOPLE.HUMAN_ORIGIN.HO_TRADITIONAL', 'Thinks traditional origin stories were first written in books.', '{"question":"How were traditional stories of origin first passed on?","wrong_answer":"In books","correct_answer":"By word of mouth from elders"}'::jsonb, 'The child meets the stories in textbooks.', 'Offer "In books" next to the right answer and ask the question again in a new context.', 'Ask a grandparent to tell a story, then compare with the book.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.PEOPLE.HUMAN_ORIGIN.HO_TRADITIONAL.M_HO_STORY_COMMUNITY_MIX', 'SOCI.G7.PEOPLE.HUMAN_ORIGIN.HO_TRADITIONAL', 'Gives one community''s story to another (Gikuyu and Mumbi to the Maasai).', '{"question":"Which community tells the story of Gikuyu and Mumbi?","wrong_answer":"The Maasai","correct_answer":"The Agikuyu"}'::jsonb, 'The stories are learnt together and the names mix.', 'Offer "The Maasai" next to the right answer and ask the question again in a new context.', 'Make story cards with the community on the back.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.PEOPLE.HUMAN_ORIGIN.HO_RELIGIOUS.M_HO_HAWA_EVE_DIFFERENT', 'SOCI.G7.PEOPLE.HUMAN_ORIGIN.HO_RELIGIOUS', 'Thinks Eve and Hawa are two different first women with nothing in common.', '{"question":"How are Eve in the Bible and Hawa in the Qur''an alike?","wrong_answer":"They are not alike at all","correct_answer":"Both are named as the first woman, made with Adam"}'::jsonb, 'Different names suggest different people.', 'Offer "They are not alike at all" next to the right answer and ask the question again in a new context.', 'Put the two names side by side with their stories.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.PEOPLE.HUMAN_ORIGIN.HO_RELIGIOUS.M_HO_PURPOSE_NONE', 'SOCI.G7.PEOPLE.HUMAN_ORIGIN.HO_RELIGIOUS', 'Misses that both kinds of story give people a purpose or duty.', '{"question":"What lesson about people do many origin stories share?","wrong_answer":"None","correct_answer":"People have a purpose and must care for the earth and each other"}'::jsonb, 'The child focuses on names and places.', 'Offer "None" next to the right answer and ask the question again in a new context.', 'Ask what each creator asked the first people to do.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.PEOPLE.EARLY_CIVILISATION.EC_FACTORS.M_EC_NILE_EVERY', 'SOCI.G7.PEOPLE.EARLY_CIVILISATION.EC_FACTORS', 'Says every ancient kingdom grew because of the River Nile.', '{"question":"Which factor helped Great Zimbabwe grow?","wrong_answer":"The yearly floods of the Nile","correct_answer":"Cattle, gold and trade with the coast"}'::jsonb, 'Egypt and the Nile are the best-known example, so the child applies it to every kingdom.', 'Offer "The yearly floods of the Nile" next to the right answer and ask the question again in a new context.', 'Ask where the Nile flows and where Great Zimbabwe stood.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.PEOPLE.EARLY_CIVILISATION.EC_FACTORS.M_EC_WHITE_BUILT', 'SOCI.G7.PEOPLE.EARLY_CIVILISATION.EC_FACTORS', 'Believes ancient African kingdoms were built by outsiders, not Africans.', '{"question":"Who built the stone walls of Great Zimbabwe?","wrong_answer":"Visitors from other lands","correct_answer":"The ancestors of the Shona people"}'::jsonb, 'Old colonial books said outsiders built Africa''s great works, and the idea still circulates.', 'Offer "Visitors from other lands" next to the right answer and ask the question again in a new context.', 'Ask which people live around the site today.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.PEOPLE.EARLY_CIVILISATION.EC_LOCATE.M_EC_EGYPT_WEST', 'SOCI.G7.PEOPLE.EARLY_CIVILISATION.EC_LOCATE', 'Puts ancient Egypt in West or Southern Africa.', '{"question":"In which part of Africa was ancient Egypt?","wrong_answer":"West Africa","correct_answer":"North-east Africa, along the Nile"}'::jsonb, 'The child has not placed Egypt on a map of Africa and guesses a region.', 'Offer "West Africa" next to the right answer and ask the question again in a new context.', 'Ask which sea lies to the north of Egypt.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.PEOPLE.EARLY_CIVILISATION.EC_LOCATE.M_EC_KONGO_NORTH', 'SOCI.G7.PEOPLE.EARLY_CIVILISATION.EC_LOCATE', 'Puts Great Zimbabwe or Kongo in the wrong region of Africa.', '{"question":"Where was Great Zimbabwe?","wrong_answer":"Near the River Congo","correct_answer":"In southern Africa, between the Limpopo and Zambezi"}'::jsonb, 'The names Congo and Kongo suggest the river, so the child places Great Zimbabwe there too.', 'Offer "Near the River Congo" next to the right answer and ask the question again in a new context.', 'Ask which kingdom lay at the mouth of the Congo River.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.PEOPLE.EARLY_CIVILISATION.EC_CONTRIB.M_EC_MIX_GIFT', 'SOCI.G7.PEOPLE.EARLY_CIVILISATION.EC_CONTRIB', 'Gives the gift of one kingdom to another, such as the pyramids to Great Zimbabwe.', '{"question":"Which kingdom is famous for hieroglyphs and papyrus?","wrong_answer":"Great Zimbabwe","correct_answer":"Ancient Egypt"}'::jsonb, 'The three kingdoms are taught together and their achievements blur.', 'Offer "Great Zimbabwe" next to the right answer and ask the question again in a new context.', 'Ask which kingdom is famous for stone walls without mortar.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.PEOPLE.EARLY_CIVILISATION.EC_CONTRIB.M_EC_NO_GIFT', 'SOCI.G7.PEOPLE.EARLY_CIVILISATION.EC_CONTRIB', 'Thinks ancient African kingdoms gave the modern world nothing.', '{"question":"Do ancient African kingdoms still matter to the world today?","wrong_answer":"No, they ended long ago","correct_answer":"Yes, their ideas are still used"}'::jsonb, 'The kingdoms ended long ago, so the child thinks their ideas ended too.', 'Offer "No, they ended long ago" next to the right answer and ask the question again in a new context.', 'Ask where the 365-day calendar began.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.PEOPLE.EARLY_CIVILISATION.EC_FACTORS.M_EC_GOLD_ONLY', 'SOCI.G7.PEOPLE.EARLY_CIVILISATION.EC_FACTORS', 'Thinks Great Zimbabwe grew only because of gold, with no farming or cattle.', '{"question":"Besides gold, what helped Great Zimbabwe grow?","wrong_answer":"Nothing else","correct_answer":"Cattle keeping, farming and trade"}'::jsonb, 'Gold is the famous fact.', 'Offer "Nothing else" next to the right answer and ask the question again in a new context.', 'List what people ate and traded there.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.PEOPLE.EARLY_CIVILISATION.EC_FACTORS.M_EC_KONGO_DESERT', 'SOCI.G7.PEOPLE.EARLY_CIVILISATION.EC_FACTORS', 'Thinks the Kingdom of Kongo grew in a desert.', '{"question":"What kind of land helped Kongo grow?","wrong_answer":"A dry desert","correct_answer":"Fertile land near the Congo River"}'::jsonb, 'The child links ancient kingdoms with Egypt''s desert.', 'Offer "A dry desert" next to the right answer and ask the question again in a new context.', 'Show the Congo basin on a vegetation map.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.PEOPLE.EARLY_CIVILISATION.EC_LOCATE.M_EC_ZIMBABWE_EAST', 'SOCI.G7.PEOPLE.EARLY_CIVILISATION.EC_LOCATE', 'Places Great Zimbabwe on the East African coast.', '{"question":"Is Great Zimbabwe on the East African coast?","wrong_answer":"Yes","correct_answer":"No, it is inland in southern Africa"}'::jsonb, 'Great Zimbabwe traded with the coast, so the child places it there.', 'Offer "Yes" next to the right answer and ask the question again in a new context.', 'Trace the trade route from Great Zimbabwe to Sofala on the coast.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.PEOPLE.EARLY_CIVILISATION.EC_LOCATE.M_EC_EGYPT_SOUTH_NILE', 'SOCI.G7.PEOPLE.EARLY_CIVILISATION.EC_LOCATE', 'Places ancient Egypt at the start of the Nile near Lake Victoria.', '{"question":"Which end of the Nile was ancient Egypt on?","wrong_answer":"The southern end near Lake Victoria","correct_answer":"The northern end near the Mediterranean Sea"}'::jsonb, 'The child knows the Nile starts near Kenya.', 'Offer "The southern end near Lake Victoria" next to the right answer and ask the question again in a new context.', 'Trace the Nile from Jinja north to Egypt.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.PEOPLE.EARLY_CIVILISATION.EC_CONTRIB.M_EC_CALENDAR_EUROPE', 'SOCI.G7.PEOPLE.EARLY_CIVILISATION.EC_CONTRIB', 'Thinks the 365-day calendar came only from Europe.', '{"question":"Which ancient kingdom gave an early 365-day calendar?","wrong_answer":"Only Europe","correct_answer":"Ancient Egypt"}'::jsonb, 'The child has only heard of European calendars.', 'Offer "Only Europe" next to the right answer and ask the question again in a new context.', 'Link the Nile flood cycle to counting the year.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.PEOPLE.EARLY_CIVILISATION.EC_CONTRIB.M_EC_MORTAR_NEEDED', 'SOCI.G7.PEOPLE.EARLY_CIVILISATION.EC_CONTRIB', 'Thinks stone walls cannot stand without cement, so Great Zimbabwe''s builders must have used it.', '{"question":"How were the walls of Great Zimbabwe built?","wrong_answer":"With cement","correct_answer":"With fitted stones and no mortar"}'::jsonb, 'The child knows modern building uses cement.', 'Offer "With cement" next to the right answer and ask the question again in a new context.', 'Stack flat stones carefully to make a small wall without glue.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.PEOPLE.SLAVERY_AND_SERVITUDE.SL_FORMS.M_SL_ONLY_PAST', 'SOCI.G7.PEOPLE.SLAVERY_AND_SERVITUDE.SL_FORMS', 'Thinks slavery ended completely and does not exist today.', '{"question":"Is there any form of slavery today?","wrong_answer":"No, it ended long ago","correct_answer":"Yes, such as trafficking and forced labour"}'::jsonb, 'Slavery is taught as history, so the child thinks it ended with the history lesson.', 'Offer "No, it ended long ago" next to the right answer and ask the question again in a new context.', 'Ask what child labour and trafficking take away from a person.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.PEOPLE.SLAVERY_AND_SERVITUDE.SL_FORMS.M_SL_SERVANT_PAID', 'SOCI.G7.PEOPLE.SLAVERY_AND_SERVITUDE.SL_FORMS', 'Treats every house helper or herder as a slave, or no unfree work as servitude.', '{"question":"What makes work servitude and not a job?","wrong_answer":"Hard work for long hours","correct_answer":"The person is not free to leave"}'::jsonb, 'The child judges by how hard the work is, not by whether the person is free.', 'Offer "Hard work for long hours" next to the right answer and ask the question again in a new context.', 'Ask: if a worker may leave, is she a slave?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.PEOPLE.SLAVERY_AND_SERVITUDE.SL_INDIAN.M_SL_ONLY_EUROPE', 'SOCI.G7.PEOPLE.SLAVERY_AND_SERVITUDE.SL_INDIAN', 'Thinks Europeans alone ran the slave trade and the Indian Ocean trade was not real.', '{"question":"Who took part in the Indian Ocean slave trade?","wrong_answer":"Only Europeans","correct_answer":"Arab and Swahili traders, and some African leaders and others"}'::jsonb, 'The Atlantic trade with Europeans is the best-known story, so the child thinks it was the only one.', 'Offer "Only Europeans" next to the right answer and ask the question again in a new context.', 'Ask which ocean is named in the trade.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.PEOPLE.SLAVERY_AND_SERVITUDE.SL_INDIAN.M_SL_NO_DEMAND', 'SOCI.G7.PEOPLE.SLAVERY_AND_SERVITUDE.SL_INDIAN', 'Gives the wrong reason, such as thinking people were taken only for food or fighting.', '{"question":"Why were people bought in the Indian Ocean trade?","wrong_answer":"To eat as food","correct_answer":"To work on plantations and in homes"}'::jsonb, 'The child does not know about plantations and household work in Arabia and the islands.', 'Offer "To eat as food" next to the right answer and ask the question again in a new context.', 'Ask where cloves were grown near Zanzibar and who worked there.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.PEOPLE.SLAVERY_AND_SERVITUDE.SL_EXTENT.M_SL_ATLANTIC_MIX', 'SOCI.G7.PEOPLE.SLAVERY_AND_SERVITUDE.SL_EXTENT', 'Mixes the Indian Ocean trade with the Atlantic trade and sends captives to America.', '{"question":"Where did the Indian Ocean slave trade take captives?","wrong_answer":"To North and South America","correct_answer":"To Arabia, India and the islands"}'::jsonb, 'Films and books show the Atlantic trade to the Americas more than the Indian Ocean trade.', 'Offer "To North and South America" next to the right answer and ask the question again in a new context.', 'Ask which ocean lies on the east of Africa.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.PEOPLE.SLAVERY_AND_SERVITUDE.SL_EXTENT.M_SL_WEST_COAST', 'SOCI.G7.PEOPLE.SLAVERY_AND_SERVITUDE.SL_EXTENT', 'Puts the trade on the west coast of Africa.', '{"question":"Which coast was the centre of the Indian Ocean trade?","wrong_answer":"The west coast","correct_answer":"The east coast, with Zanzibar and Kilwa"}'::jsonb, 'The Atlantic trade from West Africa is better known, so the child places all trade there.', 'Offer "The west coast" next to the right answer and ask the question again in a new context.', 'Ask which coast faces the Indian Ocean.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.PEOPLE.SLAVERY_AND_SERVITUDE.SL_FORMS.M_SL_DEBT_FAIR', 'SOCI.G7.PEOPLE.SLAVERY_AND_SERVITUDE.SL_FORMS', 'Thinks working forever to pay a family debt is a fair job, not servitude.', '{"question":"A boy must work for a trader for years to pay his father''s debt and cannot leave. Is this servitude?","wrong_answer":"No, it is fair payment","correct_answer":"Yes, debt bondage"}'::jsonb, 'Paying debts sounds fair.', 'Offer "No, it is fair payment" next to the right answer and ask the question again in a new context.', 'Ask whether the boy is free to leave or to go to school.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.PEOPLE.SLAVERY_AND_SERVITUDE.SL_FORMS.M_SL_TRAFFICKING_TRAVEL', 'SOCI.G7.PEOPLE.SLAVERY_AND_SERVITUDE.SL_FORMS', 'Thinks trafficking is just travelling for a job.', '{"question":"A girl is promised a job abroad, then her passport is taken and she cannot leave. What is this?","wrong_answer":"A normal job","correct_answer":"Trafficking"}'::jsonb, 'Many people do travel for work.', 'Offer "A normal job" next to the right answer and ask the question again in a new context.', 'List warning signs: passport taken, no pay, cannot leave.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.PEOPLE.SLAVERY_AND_SERVITUDE.SL_INDIAN.M_SL_MONSOON_NONE', 'SOCI.G7.PEOPLE.SLAVERY_AND_SERVITUDE.SL_INDIAN', 'Does not see the monsoon winds as a factor in the trade.', '{"question":"How did the monsoon winds help the Indian Ocean trade?","wrong_answer":"They did not","correct_answer":"They carried dhows to and from Arabia and India"}'::jsonb, 'The child does not link wind with sailing.', 'Offer "They did not" next to the right answer and ask the question again in a new context.', 'Show the wind directions in different months on a map.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.PEOPLE.SLAVERY_AND_SERVITUDE.SL_INDIAN.M_SL_IVORY_SEPARATE', 'SOCI.G7.PEOPLE.SLAVERY_AND_SERVITUDE.SL_INDIAN', 'Does not link the ivory trade with the slave trade.', '{"question":"How were ivory and slaves linked in the trade?","wrong_answer":"They were not","correct_answer":"Captives were made to carry ivory to the coast, then sold"}'::jsonb, 'The two are taught as separate trades.', 'Offer "They were not" next to the right answer and ask the question again in a new context.', 'Trace a caravan from the interior to the coast.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.PEOPLE.SLAVERY_AND_SERVITUDE.SL_EXTENT.M_SL_COAST_ONLY', 'SOCI.G7.PEOPLE.SLAVERY_AND_SERVITUDE.SL_EXTENT', 'Thinks the trade reached only the coast and never the interior.', '{"question":"Did the Indian Ocean slave trade reach Lake Victoria and the Congo basin?","wrong_answer":"No, only the coast","correct_answer":"Yes, caravan routes reached far inland"}'::jsonb, 'The coastal towns are the best-known places.', 'Offer "No, only the coast" next to the right answer and ask the question again in a new context.', 'Draw the caravan routes inland on the map.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.PEOPLE.SLAVERY_AND_SERVITUDE.SL_EXTENT.M_SL_ZANZIBAR_KENYA', 'SOCI.G7.PEOPLE.SLAVERY_AND_SERVITUDE.SL_EXTENT', 'Places Zanzibar in Kenya.', '{"question":"In which country is Zanzibar today?","wrong_answer":"Kenya","correct_answer":"Tanzania"}'::jsonb, 'Zanzibar is on the East African coast near Kenya.', 'Offer "Kenya" next to the right answer and ask the question again in a new context.', 'Point to Zanzibar on the map off the Tanzanian coast.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.PEOPLE.DEVELOPMENTS_IN_MEDIUM_O.MT_COMPARE.M_MT_BARTER_NO_PROBLEM', 'SOCI.G7.PEOPLE.DEVELOPMENTS_IN_MEDIUM_O.MT_COMPARE', 'Says barter had no problems.', '{"question":"What is a problem of barter trade?","wrong_answer":"None, it worked perfectly","correct_answer":"Both people must want what the other has"}'::jsonb, 'Swapping feels simple and fair in small, friendly exchanges the child has seen.', 'Offer "None, it worked perfectly" next to the right answer and ask the question again in a new context.', 'Ask Nyambura how she can buy cloth if the seller does not want her maize.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.PEOPLE.DEVELOPMENTS_IN_MEDIUM_O.MT_COMPARE.M_MT_BARTER_MONEY', 'SOCI.G7.PEOPLE.DEVELOPMENTS_IN_MEDIUM_O.MT_COMPARE', 'Thinks barter uses money, or that money was used from the beginning of trade.', '{"question":"What is barter?","wrong_answer":"Buying goods with coins","correct_answer":"Swapping goods for goods"}'::jsonb, 'The child has always seen trade done with money.', 'Offer "Buying goods with coins" next to the right answer and ask the question again in a new context.', 'Ask what Mwangi gives the fisherman for fish when he has no coins.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.PEOPLE.DEVELOPMENTS_IN_MEDIUM_O.MT_MONEY.M_MT_COINS_FIRST', 'SOCI.G7.PEOPLE.DEVELOPMENTS_IN_MEDIUM_O.MT_MONEY', 'Thinks coins were the first money in Africa.', '{"question":"What was used as money before coins in many parts of Africa?","wrong_answer":"Mobile money","correct_answer":"Cowrie shells, beads and iron hoes"}'::jsonb, 'The child knows money only as coins, notes and mobile money.', 'Offer "Mobile money" next to the right answer and ask the question again in a new context.', 'Ask what Kenyans on the coast used to trade for goods long ago.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.PEOPLE.DEVELOPMENTS_IN_MEDIUM_O.MT_MONEY.M_MT_ALL_GOOD', 'SOCI.G7.PEOPLE.DEVELOPMENTS_IN_MEDIUM_O.MT_MONEY', 'Thinks money brought only good effects.', '{"question":"Which is a bad effect of introducing money?","wrong_answer":"None, money only helped","correct_answer":"Debts and a gap between rich and poor"}'::jsonb, 'Money is linked with buying what you want, so it seems only good.', 'Offer "None, money only helped" next to the right answer and ask the question again in a new context.', 'Ask what happens to a person who borrows money and cannot pay.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.PEOPLE.DEVELOPMENTS_IN_MEDIUM_O.MT_COMPARE.M_MT_VALUE_EASY', 'SOCI.G7.PEOPLE.DEVELOPMENTS_IN_MEDIUM_O.MT_COMPARE', 'Thinks it was easy to agree how many hens equal a goat in barter.', '{"question":"Why was it hard to trade a cow for salt in barter?","wrong_answer":"It was easy","correct_answer":"It was hard to agree the value and to divide the cow"}'::jsonb, 'The child imagines barter of equal small things.', 'Offer "It was easy" next to the right answer and ask the question again in a new context.', 'Try trading a cow for a small bag of salt in role play.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.PEOPLE.DEVELOPMENTS_IN_MEDIUM_O.MT_COMPARE.M_MT_MONEY_FOOD', 'SOCI.G7.PEOPLE.DEVELOPMENTS_IN_MEDIUM_O.MT_COMPARE', 'Thinks money is valuable because you can eat or use it directly.', '{"question":"Why does a shopkeeper accept a 100-shilling note?","wrong_answer":"Because paper is useful","correct_answer":"Because everyone agrees it has value and will accept it"}'::jsonb, 'The child links value with use.', 'Offer "Because paper is useful" next to the right answer and ask the question again in a new context.', 'Ask what a note is worth on an island where no one accepts it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.PEOPLE.DEVELOPMENTS_IN_MEDIUM_O.MT_MONEY.M_MT_MOBILE_COLONIAL', 'SOCI.G7.PEOPLE.DEVELOPMENTS_IN_MEDIUM_O.MT_MONEY', 'Thinks mobile money came with colonial rule.', '{"question":"When did mobile money begin in Kenya?","wrong_answer":"In colonial times","correct_answer":"In the 2000s"}'::jsonb, 'All money changes are lumped together.', 'Offer "In colonial times" next to the right answer and ask the question again in a new context.', 'Put cowries, rupees, shillings and mobile money on a timeline.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.PEOPLE.DEVELOPMENTS_IN_MEDIUM_O.MT_MONEY.M_MT_TAX_NONE', 'SOCI.G7.PEOPLE.DEVELOPMENTS_IN_MEDIUM_O.MT_MONEY', 'Does not link the coming of money to taxes and wages.', '{"question":"How did colonial taxes push people to earn money?","wrong_answer":"They did not","correct_answer":"Taxes had to be paid in money, so people worked for wages"}'::jsonb, 'The child sees money as only for buying.', 'Offer "They did not" next to the right answer and ask the question again in a new context.', 'Explain the hut tax and why it needed cash.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.PEOPLE.DIVERSITY_AND_INTERPERSO.DV_FACTORS.M_DV_ONLY_TRIBE', 'SOCI.G7.PEOPLE.DIVERSITY_AND_INTERPERSO.DV_FACTORS', 'Thinks diversity means only different ethnic groups.', '{"question":"Which is a factor of human diversity?","wrong_answer":"Only the ethnic group","correct_answer":"Age, gender, religion and ability"}'::jsonb, 'Ethnic groups are the difference most talked about in Kenya, so the child stops there.', 'Offer "Only the ethnic group" next to the right answer and ask the question again in a new context.', 'Ask the child how two classmates from the same community may still differ.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.PEOPLE.DIVERSITY_AND_INTERPERSO.DV_FACTORS.M_DV_DIFFERENT_WORSE', 'SOCI.G7.PEOPLE.DIVERSITY_AND_INTERPERSO.DV_FACTORS', 'Believes people who are different are worse or must be avoided.', '{"question":"How should we treat people who are different from us?","wrong_answer":"Avoid them","correct_answer":"Respect them and learn from them"}'::jsonb, 'The child feels safer with the familiar and reads "different" as "threat".', 'Offer "Avoid them" next to the right answer and ask the question again in a new context.', 'Ask the child what a new classmate with a different language can teach the class.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.PEOPLE.DIVERSITY_AND_INTERPERSO.DV_SKILLS.M_DV_ASSERT_RUDE', 'SOCI.G7.PEOPLE.DIVERSITY_AND_INTERPERSO.DV_SKILLS', 'Thinks being assertive means being rude or loud.', '{"question":"What does it mean to be assertive?","wrong_answer":"To be loud and rude","correct_answer":"To say what you need clearly and with respect"}'::jsonb, 'Assertive people speak up, and the child has seen speaking up done loudly.', 'Offer "To be loud and rude" next to the right answer and ask the question again in a new context.', 'Ask the child to refuse a bad request politely and firmly.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.PEOPLE.DIVERSITY_AND_INTERPERSO.DV_SKILLS.M_DV_EMPATHY_PITY', 'SOCI.G7.PEOPLE.DIVERSITY_AND_INTERPERSO.DV_SKILLS', 'Mixes empathy with pity or with agreeing with everything.', '{"question":"Which shows empathy?","wrong_answer":"Feeling sorry from far away and doing nothing","correct_answer":"Trying to understand how another feels"}'::jsonb, 'Empathy and pity both involve feeling for someone, so they seem the same.', 'Offer "Feeling sorry from far away and doing nothing" next to the right answer and ask the question again in a new context.', 'Ask what Achieng does when a classmate is crying.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.PEOPLE.DIVERSITY_AND_INTERPERSO.DV_FACTORS.M_DV_DISABILITY_NOT', 'SOCI.G7.PEOPLE.DIVERSITY_AND_INTERPERSO.DV_FACTORS', 'Does not count ability or disability as part of human diversity.', '{"question":"Is disability part of human diversity?","wrong_answer":"No","correct_answer":"Yes, people have different abilities"}'::jsonb, 'Diversity is taught with culture and language examples.', 'Offer "No" next to the right answer and ask the question again in a new context.', 'Add ability to the list of differences with examples.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.PEOPLE.DIVERSITY_AND_INTERPERSO.DV_FACTORS.M_DV_SAME_BETTER', 'SOCI.G7.PEOPLE.DIVERSITY_AND_INTERPERSO.DV_FACTORS', 'Thinks a class where everyone is the same is better.', '{"question":"Is a class where everyone is the same better than a mixed one?","wrong_answer":"Yes","correct_answer":"No, different ideas and skills make a class richer"}'::jsonb, 'Sameness feels easy and calm.', 'Offer "Yes" next to the right answer and ask the question again in a new context.', 'Do a task where each learner''s skill is needed.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.PEOPLE.DIVERSITY_AND_INTERPERSO.DV_SKILLS.M_DV_PASSIVE_GOOD', 'SOCI.G7.PEOPLE.DIVERSITY_AND_INTERPERSO.DV_SKILLS', 'Thinks staying silent about your needs is the polite, good way.', '{"question":"A friend keeps taking your pen without asking. What is the best response?","wrong_answer":"Say nothing to be polite","correct_answer":"Calmly say you need it back and ask him to ask first"}'::jsonb, 'The child thinks speaking up is rude.', 'Offer "Say nothing to be polite" next to the right answer and ask the question again in a new context.', 'Practise an "I need" sentence in pairs.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.PEOPLE.DIVERSITY_AND_INTERPERSO.DV_SKILLS.M_DV_GOSSIP_HARMLESS', 'SOCI.G7.PEOPLE.DIVERSITY_AND_INTERPERSO.DV_SKILLS', 'Sorts gossip as harmless fun, not as an undesirable attribute.', '{"question":"Is gossiping about a classmate a desirable or undesirable attribute?","wrong_answer":"Desirable, it is fun","correct_answer":"Undesirable, it hurts people and trust"}'::jsonb, 'Gossip feels like ordinary chatter.', 'Offer "Desirable, it is fun" next to the right answer and ask the question again in a new context.', 'Ask how the classmate feels when they hear it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.PEOPLE.PEACEFUL_COEXISTENCE.PE_QUALITIES.M_PE_PEACE_WEAK', 'SOCI.G7.PEOPLE.PEACEFUL_COEXISTENCE.PE_QUALITIES', 'Thinks a peaceful person is weak or afraid.', '{"question":"Why does a peaceful person walk away from a fight?","wrong_answer":"Because he is afraid","correct_answer":"Because he chooses to solve it peacefully"}'::jsonb, 'Films and playground talk praise fighting back as brave.', 'Offer "Because he is afraid" next to the right answer and ask the question again in a new context.', 'Ask whether it takes courage to forgive.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.PEOPLE.PEACEFUL_COEXISTENCE.PE_QUALITIES.M_PE_REVENGE_FAIR', 'SOCI.G7.PEOPLE.PEACEFUL_COEXISTENCE.PE_QUALITIES', 'Thinks revenge is fair because it pays back a wrong.', '{"question":"Someone insulted Otieno. What does a peaceful person do?","wrong_answer":"Insults him back","correct_answer":"Tells him calmly how he feels"}'::jsonb, 'Paying back feels like justice to the child.', 'Offer "Insults him back" next to the right answer and ask the question again in a new context.', 'Ask what happens after both people insult each other.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.PEOPLE.PEACEFUL_COEXISTENCE.PE_FACTORS.M_PE_FAIR_SKIP', 'SOCI.G7.PEOPLE.PEACEFUL_COEXISTENCE.PE_FACTORS', 'Does not link fairness and equal sharing to peace.', '{"question":"Which promotes peace in a community?","wrong_answer":"Giving all the resources to one group","correct_answer":"Sharing resources fairly"}'::jsonb, 'The child sees peace as a feeling between people, not as linked to how things are shared.', 'Offer "Giving all the resources to one group" next to the right answer and ask the question again in a new context.', 'Ask what happens when one village is given all the water.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.PEOPLE.PEACEFUL_COEXISTENCE.PE_FACTORS.M_PE_ARMS_PEACE', 'SOCI.G7.PEOPLE.PEACEFUL_COEXISTENCE.PE_FACTORS', 'Thinks more weapons make a community more peaceful.', '{"question":"Which makes a community more peaceful?","wrong_answer":"Buying more weapons","correct_answer":"Talking and keeping the law"}'::jsonb, 'The child thinks being stronger stops others from attacking.', 'Offer "Buying more weapons" next to the right answer and ask the question again in a new context.', 'Ask what dialogue between two clans can solve that a gun cannot.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.PEOPLE.PEACEFUL_COEXISTENCE.PE_RESOLVE.M_PE_TAKE_SIDES', 'SOCI.G7.PEOPLE.PEACEFUL_COEXISTENCE.PE_RESOLVE', 'Believes a mediator takes the side of the person who asked.', '{"question":"What does a mediator do?","wrong_answer":"Takes the side of one person","correct_answer":"Helps both sides agree, without taking a side"}'::jsonb, 'The child thinks whoever asks for help gets someone on their side.', 'Offer "Takes the side of one person" next to the right answer and ask the question again in a new context.', 'Ask why a referee in football should not support one team.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.PEOPLE.PEACEFUL_COEXISTENCE.PE_RESOLVE.M_PE_SOLVE_FIRST', 'SOCI.G7.PEOPLE.PEACEFUL_COEXISTENCE.PE_RESOLVE', 'Jumps to solutions before listening.', '{"question":"What is the first step in solving a conflict peacefully?","wrong_answer":"Decide who is guilty","correct_answer":"Stay calm and listen to each side"}'::jsonb, 'The child wants the quarrel over quickly and skips listening.', 'Offer "Decide who is guilty" next to the right answer and ask the question again in a new context.', 'Ask what would happen if the teacher decided without hearing both learners.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.PEOPLE.PEACEFUL_COEXISTENCE.PE_QUALITIES.M_PE_AGREE_ALL', 'SOCI.G7.PEOPLE.PEACEFUL_COEXISTENCE.PE_QUALITIES', 'Thinks a peaceful person agrees with everyone and never disagrees.', '{"question":"Can a peaceful person disagree with others?","wrong_answer":"No, they agree with everyone","correct_answer":"Yes, calmly and respectfully"}'::jsonb, 'Peace is mistaken for silence.', 'Offer "No, they agree with everyone" next to the right answer and ask the question again in a new context.', 'Act a calm disagreement.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.PEOPLE.PEACEFUL_COEXISTENCE.PE_QUALITIES.M_PE_FORGIVE_FORGET', 'SOCI.G7.PEOPLE.PEACEFUL_COEXISTENCE.PE_QUALITIES', 'Thinks forgiving means the wrong did not matter.', '{"question":"Does forgiving someone mean what they did was right?","wrong_answer":"Yes","correct_answer":"No, it means letting go of revenge while the wrong is still named"}'::jsonb, 'Forgiving is confused with excusing.', 'Offer "Yes" next to the right answer and ask the question again in a new context.', 'Discuss forgiving while still asking the person to change.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.PEOPLE.PEACEFUL_COEXISTENCE.PE_FACTORS.M_PE_ELDERS_NONE', 'SOCI.G7.PEOPLE.PEACEFUL_COEXISTENCE.PE_FACTORS', 'Does not see elders and peace committees as factors that promote peace.', '{"question":"How do elders promote peace in a community?","wrong_answer":"They do not","correct_answer":"By settling disputes and advising"}'::jsonb, 'The child sees peace as the work of police only.', 'Offer "They do not" next to the right answer and ask the question again in a new context.', 'Recall elders mediating in a Grade 5 story.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.PEOPLE.PEACEFUL_COEXISTENCE.PE_FACTORS.M_PE_TOLERANCE_NONE', 'SOCI.G7.PEOPLE.PEACEFUL_COEXISTENCE.PE_FACTORS', 'Does not see religious tolerance as a factor in peace.', '{"question":"Why does respect between faiths help peace?","wrong_answer":"It does not","correct_answer":"People of different faiths live together without quarrels"}'::jsonb, 'The child does not link faith differences with conflict.', 'Offer "It does not" next to the right answer and ask the question again in a new context.', 'Show an interfaith event photo.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.PEOPLE.PEACEFUL_COEXISTENCE.PE_RESOLVE.M_PE_RECONCILE_START', 'SOCI.G7.PEOPLE.PEACEFUL_COEXISTENCE.PE_RESOLVE', 'Puts reconciliation at the start, before the problem is understood.', '{"question":"When does reconciliation come in solving a conflict?","wrong_answer":"First","correct_answer":"At the end, after an agreement"}'::jsonb, 'The child wants the friendship back at once.', 'Offer "First" next to the right answer and ask the question again in a new context.', 'Order the steps on cards.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.PEOPLE.PEACEFUL_COEXISTENCE.PE_RESOLVE.M_PE_VIOLENCE_METHOD', 'SOCI.G7.PEOPLE.PEACEFUL_COEXISTENCE.PE_RESOLVE', 'Lists fighting as one way of resolving conflict.', '{"question":"Is fighting a method of resolving conflict?","wrong_answer":"Yes, the winner decides","correct_answer":"No, it makes conflict worse"}'::jsonb, 'The child has seen fights "end" quarrels.', 'Offer "Yes, the winner decides" next to the right answer and ask the question again in a new context.', 'Ask what happens after the fight.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.COMMUN.COMMUNITY_SERVICE_LEARNI.CS_MEANING.M_CS_JUST_WORK', 'SOCI.G7.COMMUN.COMMUNITY_SERVICE_LEARNI.CS_MEANING', 'Thinks CSL is only free work or punishment.', '{"question":"What is community service learning?","wrong_answer":"Free work as a punishment","correct_answer":"Learning by serving a real community need"}'::jsonb, 'Some schools use cleaning as a punishment, so service looks like punishment.', 'Offer "Free work as a punishment" next to the right answer and ask the question again in a new context.', 'Ask what the learners learn when they plant trees in the village.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.COMMUN.COMMUNITY_SERVICE_LEARNI.CS_MEANING.M_CS_NEED_WANT', 'SOCI.G7.COMMUN.COMMUNITY_SERVICE_LEARNI.CS_MEANING', 'Picks a project that the learners want but the community does not need.', '{"question":"Which is a community need?","wrong_answer":"A new game for the learners","correct_answer":"Clean water for the school"}'::jsonb, 'The child thinks first of what learners would enjoy.', 'Offer "A new game for the learners" next to the right answer and ask the question again in a new context.', 'Ask the child who in the community benefits from the project.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.COMMUN.COMMUNITY_SERVICE_LEARNI.CS_STEPS.M_CS_ACT_FIRST', 'SOCI.G7.COMMUN.COMMUNITY_SERVICE_LEARNI.CS_STEPS', 'Starts the activity before identifying the need and planning.', '{"question":"What comes first in a CSL project?","wrong_answer":"Doing the activity","correct_answer":"Identifying the need"}'::jsonb, 'Doing feels like the real work, so the child skips planning.', 'Offer "Doing the activity" next to the right answer and ask the question again in a new context.', 'Ask what might go wrong if the class started to dig before they knew what was needed.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.COMMUN.COMMUNITY_SERVICE_LEARNI.CS_STEPS.M_CS_NO_REPORT', 'SOCI.G7.COMMUN.COMMUNITY_SERVICE_LEARNI.CS_STEPS', 'Thinks the project ends when the activity is done, with no report or reflection.', '{"question":"What is the last step of a CSL project?","wrong_answer":"Stop and forget it","correct_answer":"Report and reflect on what was learnt"}'::jsonb, 'The child thinks the job ends when the visible work ends.', 'Offer "Stop and forget it" next to the right answer and ask the question again in a new context.', 'Ask what the class can improve next time.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.COMMUN.COMMUNITY_SERVICE_LEARNI.CS_MEANING.M_CS_CHARITY_SAME', 'SOCI.G7.COMMUN.COMMUNITY_SERVICE_LEARNI.CS_MEANING', 'Thinks CSL is the same as giving charity, with no learning.', '{"question":"How is CSL different from just giving gifts?","wrong_answer":"It is the same","correct_answer":"Learners serve a real need and learn skills and values while doing it"}'::jsonb, 'Both involve helping.', 'Offer "It is the same" next to the right answer and ask the question again in a new context.', 'Ask what learners learnt while planting trees.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.COMMUN.COMMUNITY_SERVICE_LEARNI.CS_MEANING.M_CS_SCHOOL_ONLY', 'SOCI.G7.COMMUN.COMMUNITY_SERVICE_LEARNI.CS_MEANING', 'Thinks CSL can only happen inside the school compound.', '{"question":"Can a CSL project be done outside the school?","wrong_answer":"No","correct_answer":"Yes, in the community, such as cleaning a market"}'::jsonb, 'The child thinks school work stays at school.', 'Offer "No" next to the right answer and ask the question again in a new context.', 'List places near school with needs.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.COMMUN.COMMUNITY_SERVICE_LEARNI.CS_STEPS.M_CS_PLAN_VAGUE', 'SOCI.G7.COMMUN.COMMUNITY_SERVICE_LEARNI.CS_STEPS', 'Thinks a plan only needs a date, not tasks, people and resources.', '{"question":"What should a CSL plan include?","wrong_answer":"Only the date","correct_answer":"Tasks, people, time and resources"}'::jsonb, 'The child thinks of a plan as a calendar entry.', 'Offer "Only the date" next to the right answer and ask the question again in a new context.', 'Fill in a plan sheet with four columns.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.COMMUN.COMMUNITY_SERVICE_LEARNI.CS_STEPS.M_CS_REFLECT_SKIP', 'SOCI.G7.COMMUN.COMMUNITY_SERVICE_LEARNI.CS_STEPS', 'Thinks reflecting is the same as reporting.', '{"question":"What does reflecting on a CSL project mean?","wrong_answer":"Writing the report","correct_answer":"Thinking about what was learnt and what to do better"}'::jsonb, 'Both come at the end.', 'Offer "Writing the report" next to the right answer and ask the question again in a new context.', 'Ask two questions: what did we do (report), what did we learn (reflect)?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.NATURA.HISTORICAL_INFORMATION.HI_SOURCES.M_HI_ONLY_BOOKS', 'SOCI.G7.NATURA.HISTORICAL_INFORMATION.HI_SOURCES', 'Thinks history comes only from books.', '{"question":"Which is a source of history?","wrong_answer":"Only textbooks","correct_answer":"Oral stories told by elders"}'::jsonb, 'History lessons use textbooks, so the child thinks books are where history comes from.', 'Offer "Only textbooks" next to the right answer and ask the question again in a new context.', 'Ask where the history of the community was kept before writing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.NATURA.HISTORICAL_INFORMATION.HI_SOURCES.M_HI_ARCH_ORAL', 'SOCI.G7.NATURA.HISTORICAL_INFORMATION.HI_SOURCES', 'Mixes archaeological and oral sources.', '{"question":"A fossil and old pots dug from the ground are which source?","wrong_answer":"Oral tradition","correct_answer":"Archaeological"}'::jsonb, 'Both sources are about the far past and the words are new.', 'Offer "Oral tradition" next to the right answer and ask the question again in a new context.', 'Ask: do you hear or dig the evidence?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.NATURA.HISTORICAL_INFORMATION.HI_PRIMARY.M_HI_NEW_PRIMARY', 'SOCI.G7.NATURA.HISTORICAL_INFORMATION.HI_PRIMARY', 'Thinks a recent source is primary and an old book is always secondary.', '{"question":"A textbook written in 2024 about the 1884 Berlin Conference is which source?","wrong_answer":"Primary","correct_answer":"Secondary"}'::jsonb, 'The child uses age as the test: new means first-hand, old means second-hand.', 'Offer "Primary" next to the right answer and ask the question again in a new context.', 'Ask whether the author was at the conference.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.NATURA.HISTORICAL_INFORMATION.HI_PRIMARY.M_HI_PHOTO_SECONDARY', 'SOCI.G7.NATURA.HISTORICAL_INFORMATION.HI_PRIMARY', 'Thinks a photograph or diary is secondary because it is old.', '{"question":"A diary a soldier wrote during the First World War is which source?","wrong_answer":"Secondary","correct_answer":"Primary"}'::jsonb, 'The child uses age as the test and old things feel second-hand.', 'Offer "Secondary" next to the right answer and ask the question again in a new context.', 'Ask who wrote the diary and when.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.NATURA.HISTORICAL_INFORMATION.HI_PRESERVE.M_HI_ORAL_LOST', 'SOCI.G7.NATURA.HISTORICAL_INFORMATION.HI_PRESERVE', 'Thinks oral history cannot be kept.', '{"question":"How has oral history been kept?","wrong_answer":"It cannot be kept","correct_answer":"In songs and stories, and now by recording"}'::jsonb, 'The child thinks only writing lasts.', 'Offer "It cannot be kept" next to the right answer and ask the question again in a new context.', 'Ask how a grandmother passes on a proverb.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.NATURA.HISTORICAL_INFORMATION.HI_PRESERVE.M_HI_KEEP_OUTSIDE', 'SOCI.G7.NATURA.HISTORICAL_INFORMATION.HI_PRESERVE', 'Says objects are best kept by leaving them in the open.', '{"question":"How are old objects best preserved?","wrong_answer":"Left out in the open","correct_answer":"In museums and archives"}'::jsonb, 'The child thinks objects belong where they were found.', 'Offer "Left out in the open" next to the right answer and ask the question again in a new context.', 'Ask what rain and sun do to old paper.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.NATURA.HISTORICAL_INFORMATION.HI_SOURCES.M_HI_LANGUAGE_NOT', 'SOCI.G7.NATURA.HISTORICAL_INFORMATION.HI_SOURCES', 'Does not count language as a source of history.', '{"question":"How can similar words in two languages give historical information?","wrong_answer":"They cannot","correct_answer":"They show the peoples were once linked or traded"}'::jsonb, 'The child sees language only as speech.', 'Offer "They cannot" next to the right answer and ask the question again in a new context.', 'Compare a few shared words in two Bantu languages.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.NATURA.HISTORICAL_INFORMATION.HI_SOURCES.M_HI_FOSSIL_ROCK', 'SOCI.G7.NATURA.HISTORICAL_INFORMATION.HI_SOURCES', 'Thinks a fossil is just a rock with no information.', '{"question":"What can a fossil tell historians?","wrong_answer":"Nothing, it is a rock","correct_answer":"What living things were like long ago"}'::jsonb, 'Fossils look like stones.', 'Offer "Nothing, it is a rock" next to the right answer and ask the question again in a new context.', 'Show a fossil photo with the bone shape visible.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.NATURA.HISTORICAL_INFORMATION.HI_PRIMARY.M_HI_INTERVIEW_ANY', 'SOCI.G7.NATURA.HISTORICAL_INFORMATION.HI_PRIMARY', 'Thinks an interview is always primary, even with someone who was not there.', '{"question":"You interview your grandmother about her own wedding in 1970. What kind of source is it?","wrong_answer":"Secondary, it is old","correct_answer":"Primary, she was there"}'::jsonb, 'Age is used instead of presence.', 'Offer "Secondary, it is old" next to the right answer and ask the question again in a new context.', 'Ask: was the speaker there?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.NATURA.HISTORICAL_INFORMATION.HI_PRIMARY.M_HI_DOCUMENTARY_PRIMARY', 'SOCI.G7.NATURA.HISTORICAL_INFORMATION.HI_PRIMARY', 'Thinks a documentary film is primary because it has pictures.', '{"question":"A documentary made in 2020 about independence in 1963. Primary or secondary?","wrong_answer":"Primary, it has films","correct_answer":"Secondary"}'::jsonb, 'Pictures feel like being there.', 'Offer "Primary, it has films" next to the right answer and ask the question again in a new context.', 'Ask who made it and when.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.NATURA.HISTORICAL_INFORMATION.HI_PRESERVE.M_HI_ARCHIVE_SHOP', 'SOCI.G7.NATURA.HISTORICAL_INFORMATION.HI_PRESERVE', 'Thinks an archive is a shop that sells old things.', '{"question":"What is an archive?","wrong_answer":"A shop for old things","correct_answer":"A place that keeps old records and documents"}'::jsonb, 'The word is new.', 'Offer "A shop for old things" next to the right answer and ask the question again in a new context.', 'Show the Kenya National Archives photo.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.NATURA.HISTORICAL_INFORMATION.HI_PRESERVE.M_HI_DIGITAL_NONE', 'SOCI.G7.NATURA.HISTORICAL_INFORMATION.HI_PRESERVE', 'Does not see digital recording as a way of keeping history.', '{"question":"How can a phone help keep history?","wrong_answer":"It cannot","correct_answer":"By recording elders'' stories and photographing old objects"}'::jsonb, 'The child sees phones for entertainment.', 'Offer "It cannot" next to the right answer and ask the question again in a new context.', 'Record a short story from an elder.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.NATURA.HISTORICAL_DEVELOPMENT_O.EA_WHERE.M_EA_EAST_ONLY', 'SOCI.G7.NATURA.HISTORICAL_DEVELOPMENT_O.EA_WHERE', 'Thinks farming began in Africa only in the Nile Valley.', '{"question":"Where else did early farming begin in Africa?","wrong_answer":"Nowhere else","correct_answer":"The Ethiopian highlands and West African savanna"}'::jsonb, 'Egypt is the most taught example of early farming.', 'Offer "Nowhere else" next to the right answer and ask the question again in a new context.', 'Ask where teff and coffee come from.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.NATURA.HISTORICAL_DEVELOPMENT_O.EA_WHERE.M_EA_DRY_FARM', 'SOCI.G7.NATURA.HISTORICAL_DEVELOPMENT_O.EA_WHERE', 'Believes early farming began in the driest places.', '{"question":"What helped early farming begin in a place?","wrong_answer":"No water and poor soil","correct_answer":"Fertile soil and reliable water"}'::jsonb, 'The child links Egypt with desert and forgets the river.', 'Offer "No water and poor soil" next to the right answer and ask the question again in a new context.', 'Ask what a plant needs to grow.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.NATURA.HISTORICAL_DEVELOPMENT_O.EA_NILE.M_EA_FLOOD_BAD', 'SOCI.G7.NATURA.HISTORICAL_DEVELOPMENT_O.EA_NILE', 'Believes the Nile flood only destroyed farms.', '{"question":"What did the yearly Nile flood leave?","wrong_answer":"Only damage","correct_answer":"Rich silt that made the soil fertile"}'::jsonb, 'Floods today destroy homes, so the child thinks every flood is harmful.', 'Offer "Only damage" next to the right answer and ask the question again in a new context.', 'Ask why Egyptian farmers waited for the flood each year.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.NATURA.HISTORICAL_DEVELOPMENT_O.EA_NILE.M_EA_NO_SURPLUS', 'SOCI.G7.NATURA.HISTORICAL_DEVELOPMENT_O.EA_NILE', 'Does not link a food surplus to towns, writing and trades.', '{"question":"What did a food surplus allow?","wrong_answer":"Everyone to farm","correct_answer":"Some people to become scribes, builders and traders"}'::jsonb, 'The child does not think about who fed the builders and scribes.', 'Offer "Everyone to farm" next to the right answer and ask the question again in a new context.', 'Ask who feeds the builder if he does not farm.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.NATURA.HISTORICAL_DEVELOPMENT_O.EA_WHERE.M_EA_CROP_MIX', 'SOCI.G7.NATURA.HISTORICAL_DEVELOPMENT_O.EA_WHERE', 'Matches a crop to the wrong region (teff to the Nile Valley).', '{"question":"Where was teff first grown?","wrong_answer":"The Nile Valley","correct_answer":"The Ethiopian highlands"}'::jsonb, 'The regions and crops are learnt together.', 'Offer "The Nile Valley" next to the right answer and ask the question again in a new context.', 'Match crop cards to a map.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.NATURA.HISTORICAL_DEVELOPMENT_O.EA_WHERE.M_EA_ANIMALS_WILD', 'SOCI.G7.NATURA.HISTORICAL_DEVELOPMENT_O.EA_WHERE', 'Thinks early farmers kept wild animals such as lions.', '{"question":"Which animals did early farmers in Africa rear?","wrong_answer":"Lions and zebras","correct_answer":"Cattle, sheep, goats and donkeys"}'::jsonb, 'The child links Africa with wild animals.', 'Offer "Lions and zebras" next to the right answer and ask the question again in a new context.', 'Sort animals into domestic and wild.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.NATURA.HISTORICAL_DEVELOPMENT_O.EA_NILE.M_EA_SHADUF_PUMP', 'SOCI.G7.NATURA.HISTORICAL_DEVELOPMENT_O.EA_NILE', 'Thinks the shaduf was a motor pump.', '{"question":"What was the shaduf?","wrong_answer":"A motor pump","correct_answer":"A pole with a bucket and a weight used to lift water"}'::jsonb, 'The child knows only modern pumps.', 'Offer "A motor pump" next to the right answer and ask the question again in a new context.', 'Draw or build a shaduf with a stick and a stone.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.NATURA.HISTORICAL_DEVELOPMENT_O.EA_NILE.M_EA_WRITING_UNRELATED', 'SOCI.G7.NATURA.HISTORICAL_DEVELOPMENT_O.EA_NILE', 'Does not link farming records with the start of writing.', '{"question":"How did farming help writing begin in Egypt?","wrong_answer":"It did not","correct_answer":"Records of harvests and taxes needed to be kept"}'::jsonb, 'Writing seems unrelated to farming.', 'Offer "It did not" next to the right answer and ask the question again in a new context.', 'Ask how a ruler would know how much grain was stored.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.NATURA.MAPS_AND_MAP_WORK.MM_AFRICA.M_MM_BIGGEST', 'SOCI.G7.NATURA.MAPS_AND_MAP_WORK.MM_AFRICA', 'Calls Africa the largest continent.', '{"question":"Where does Africa rank by size among the continents?","wrong_answer":"The largest","correct_answer":"The second largest"}'::jsonb, 'Africa looks large on many maps and the child has not compared it with Asia.', 'Offer "The largest" next to the right answer and ask the question again in a new context.', 'Ask which continent is bigger than Africa.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.NATURA.MAPS_AND_MAP_WORK.MM_AFRICA.M_MM_EQUATOR_SIDE', 'SOCI.G7.NATURA.MAPS_AND_MAP_WORK.MM_AFRICA', 'Thinks the equator crosses only the north or the south of Africa.', '{"question":"Which line crosses the middle of Africa?","wrong_answer":"The Prime Meridian only","correct_answer":"The equator"}'::jsonb, 'The child knows the equator crosses Kenya and thinks it stays in the east.', 'Offer "The Prime Meridian only" next to the right answer and ask the question again in a new context.', 'Ask which country on the equator the child knows.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.NATURA.MAPS_AND_MAP_WORK.MM_LATLONG.M_MM_LAT_LON_SWAP', 'SOCI.G7.NATURA.MAPS_AND_MAP_WORK.MM_LATLONG', 'Swaps latitude and longitude.', '{"question":"Which measures how far north or south a place is?","wrong_answer":"Longitude","correct_answer":"Latitude"}'::jsonb, 'The two words sound alike and are taught together.', 'Offer "Longitude" next to the right answer and ask the question again in a new context.', 'Ask which lines run east to west.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.NATURA.MAPS_AND_MAP_WORK.MM_LATLONG.M_MM_NEGATIVE_HEM', 'SOCI.G7.NATURA.MAPS_AND_MAP_WORK.MM_LATLONG', 'Says a southern latitude is in the northern hemisphere.', '{"question":"A town is at 5 degrees south. Which hemisphere?","wrong_answer":"Northern","correct_answer":"Southern"}'::jsonb, 'The child sees the latitude number and forgets the letter.', 'Offer "Northern" next to the right answer and ask the question again in a new context.', 'Ask which side of the equator south is.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.NATURA.MAPS_AND_MAP_WORK.MM_TIME.M_MM_EAST_BEHIND', 'SOCI.G7.NATURA.MAPS_AND_MAP_WORK.MM_TIME', 'Subtracts time for a place east of Greenwich, as if it were behind.', '{"question":"It is noon at Greenwich. What is the time at 30 degrees east?","wrong_answer":"10:00 am","correct_answer":"2:00 pm"}'::jsonb, 'The child thinks the sun reaches the west first because maps are read from the left.', 'Offer "10:00 am" next to the right answer and ask the question again in a new context.', 'Ask where the sun rises first, east or west.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.NATURA.MAPS_AND_MAP_WORK.MM_TIME.M_MM_DEGREE_HOUR', 'SOCI.G7.NATURA.MAPS_AND_MAP_WORK.MM_TIME', 'Takes one degree as one hour.', '{"question":"How many degrees of longitude make one hour?","wrong_answer":"1 degree","correct_answer":"15 degrees"}'::jsonb, 'Both are units on the same calculation and the child pairs them one to one.', 'Offer "1 degree" next to the right answer and ask the question again in a new context.', 'Ask: 360 degrees in 24 hours is how many degrees an hour?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.NATURA.MAPS_AND_MAP_WORK.MM_FEATURES.M_MM_SAHARA_COLD', 'SOCI.G7.NATURA.MAPS_AND_MAP_WORK.MM_FEATURES', 'Mixes up the largest hot desert with other deserts in the south.', '{"question":"Which is the largest hot desert in Africa?","wrong_answer":"The Kalahari","correct_answer":"The Sahara"}'::jsonb, 'The child remembers the Kalahari name but not which desert is the largest.', 'Offer "The Kalahari" next to the right answer and ask the question again in a new context.', 'Ask which desert lies in the north of Africa.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.NATURA.MAPS_AND_MAP_WORK.MM_FEATURES.M_MM_KENYA_HIGHEST', 'SOCI.G7.NATURA.MAPS_AND_MAP_WORK.MM_FEATURES', 'Says Mount Kenya is the highest mountain in Africa.', '{"question":"Which is the highest mountain in Africa?","wrong_answer":"Mount Kenya","correct_answer":"Mount Kilimanjaro"}'::jsonb, 'Mount Kenya is the highest mountain the child knows, in their own country.', 'Offer "Mount Kenya" next to the right answer and ask the question again in a new context.', 'Ask which country holds Kilimanjaro.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.NATURA.MAPS_AND_MAP_WORK.MM_AFRICA.M_MM_OCEAN_SWAP', 'SOCI.G7.NATURA.MAPS_AND_MAP_WORK.MM_AFRICA', 'Puts the Atlantic Ocean on the east of Africa and the Indian Ocean on the west.', '{"question":"Which ocean lies to the west of Africa?","wrong_answer":"The Indian Ocean","correct_answer":"The Atlantic Ocean"}'::jsonb, 'The child knows Kenya is on the Indian Ocean and is unsure of the rest.', 'Offer "The Indian Ocean" next to the right answer and ask the question again in a new context.', 'Trace the coast of Africa on a globe naming each ocean.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.NATURA.MAPS_AND_MAP_WORK.MM_AFRICA.M_MM_AFRICA_COUNTRY', 'SOCI.G7.NATURA.MAPS_AND_MAP_WORK.MM_AFRICA', 'Talks of Africa as if it were one country.', '{"question":"Is Africa a country?","wrong_answer":"Yes","correct_answer":"No, a continent with more than 50 countries"}'::jsonb, 'The child hears "Africa" used like a country name.', 'Offer "Yes" next to the right answer and ask the question again in a new context.', 'Count the countries on a political map.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.NATURA.MAPS_AND_MAP_WORK.MM_LATLONG.M_MM_LONG_FIRST', 'SOCI.G7.NATURA.MAPS_AND_MAP_WORK.MM_LATLONG', 'Reads the longitude before the latitude when giving a position.', '{"question":"A table gives \"0 degrees, 32 degrees E\". Which number is the latitude?","wrong_answer":"32 degrees E","correct_answer":"0 degrees"}'::jsonb, 'The child reads east-west first, like x on a graph.', 'Offer "32 degrees E" next to the right answer and ask the question again in a new context.', 'Practise saying "latitude first" with a finger on the table.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.NATURA.MAPS_AND_MAP_WORK.MM_LATLONG.M_MM_TROPIC_EQUATOR', 'SOCI.G7.NATURA.MAPS_AND_MAP_WORK.MM_LATLONG', 'Mixes up the Tropic of Cancer and the equator.', '{"question":"Which line is at about 23.5 degrees north?","wrong_answer":"The equator","correct_answer":"The Tropic of Cancer"}'::jsonb, 'Both are lines of latitude across Africa.', 'Offer "The equator" next to the right answer and ask the question again in a new context.', 'Label the equator, both tropics and their degrees on the board.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.NATURA.MAPS_AND_MAP_WORK.MM_TIME.M_MM_MINUTES_DEGREE', 'SOCI.G7.NATURA.MAPS_AND_MAP_WORK.MM_TIME', 'Takes one degree as one minute instead of four.', '{"question":"How many minutes of time is one degree of longitude?","wrong_answer":"1 minute","correct_answer":"4 minutes"}'::jsonb, 'The child divides 60 minutes by 15 and gets confused.', 'Offer "1 minute" next to the right answer and ask the question again in a new context.', 'Show 60 minutes ÷ 15 degrees = 4 minutes per degree.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.NATURA.MAPS_AND_MAP_WORK.MM_TIME.M_MM_TIME_ADD_WEST', 'SOCI.G7.NATURA.MAPS_AND_MAP_WORK.MM_TIME', 'Adds time for a place west of Greenwich.', '{"question":"It is noon at Greenwich. What is the time at 15 degrees west?","wrong_answer":"1:00 pm","correct_answer":"11:00 am"}'::jsonb, 'The child always adds.', 'Offer "1:00 pm" next to the right answer and ask the question again in a new context.', 'Show the sun rising in the east: places in the west see noon later.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.NATURA.MAPS_AND_MAP_WORK.MM_FEATURES.M_MM_NILE_SOUTH', 'SOCI.G7.NATURA.MAPS_AND_MAP_WORK.MM_FEATURES', 'Says the Nile flows south.', '{"question":"In which direction does the Nile flow?","wrong_answer":"South","correct_answer":"North, to the Mediterranean Sea"}'::jsonb, 'Rivers on maps are thought to flow "down" the page.', 'Offer "South" next to the right answer and ask the question again in a new context.', 'Trace the Nile from Lake Victoria to the Mediterranean.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.NATURA.MAPS_AND_MAP_WORK.MM_FEATURES.M_MM_LARGEST_LAKE', 'SOCI.G7.NATURA.MAPS_AND_MAP_WORK.MM_FEATURES', 'Names Lake Tanganyika as Africa''s largest lake.', '{"question":"Which is the largest lake in Africa?","wrong_answer":"Lake Tanganyika","correct_answer":"Lake Victoria"}'::jsonb, 'Lake Tanganyika is famous as very deep and long.', 'Offer "Lake Tanganyika" next to the right answer and ask the question again in a new context.', 'Compare areas in a table: largest by area is Victoria.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.NATURA.EARTH_AND_THE_SOLAR_SYST.ES_ORIGIN_SIZE.M_ES_FLAT', 'SOCI.G7.NATURA.EARTH_AND_THE_SOLAR_SYST.ES_ORIGIN_SIZE', 'Believes the earth is flat.', '{"question":"What is the shape of the earth?","wrong_answer":"Flat like a plate","correct_answer":"Almost round, like a ball"}'::jsonb, 'The ground looks flat from where the child stands.', 'Offer "Flat like a plate" next to the right answer and ask the question again in a new context.', 'Ask why a ship seems to sink behind the horizon.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.NATURA.EARTH_AND_THE_SOLAR_SYST.ES_ORIGIN_SIZE.M_ES_THIRD_SUN', 'SOCI.G7.NATURA.EARTH_AND_THE_SOLAR_SYST.ES_ORIGIN_SIZE', 'Gets the order of the earth among the planets wrong.', '{"question":"Which planet from the Sun is the earth?","wrong_answer":"The first","correct_answer":"The third"}'::jsonb, 'The child has not learnt the order of the planets.', 'Offer "The first" next to the right answer and ask the question again in a new context.', 'Ask the child to list Mercury, Venus, then the earth.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.NATURA.EARTH_AND_THE_SOLAR_SYST.ES_MOTION.M_ES_SUN_MOVES', 'SOCI.G7.NATURA.EARTH_AND_THE_SOLAR_SYST.ES_MOTION', 'Says day and night happen because the Sun goes round the earth.', '{"question":"What causes day and night?","wrong_answer":"The Sun going round the earth","correct_answer":"The earth rotating on its axis"}'::jsonb, 'The sun seems to move across the sky each day.', 'Offer "The Sun going round the earth" next to the right answer and ask the question again in a new context.', 'Ask which side of the earth faces the Sun at noon.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.NATURA.EARTH_AND_THE_SOLAR_SYST.ES_MOTION.M_ES_SEASON_DISTANCE', 'SOCI.G7.NATURA.EARTH_AND_THE_SOLAR_SYST.ES_MOTION', 'Says seasons come because the earth is closer to the Sun in summer.', '{"question":"What causes the seasons in many parts of the world?","wrong_answer":"The earth moving closer to and away from the Sun","correct_answer":"The tilt of the axis and the earth''s revolution"}'::jsonb, 'Being closer to a fire is hotter, so the child applies it to the sun.', 'Offer "The earth moving closer to and away from the Sun" next to the right answer and ask the question again in a new context.', 'Ask why it is winter in the south when it is summer in the north.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.NATURA.EARTH_AND_THE_SOLAR_SYST.ES_STRUCTURE.M_ES_CORE_COLD', 'SOCI.G7.NATURA.EARTH_AND_THE_SOLAR_SYST.ES_STRUCTURE', 'Thinks the centre of the earth is cold or hollow.', '{"question":"What is the inner core like?","wrong_answer":"Cold and hollow","correct_answer":"Solid and very hot"}'::jsonb, 'The deep soil the child has touched is cool.', 'Offer "Cold and hollow" next to the right answer and ask the question again in a new context.', 'Ask what comes out of a volcano.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.NATURA.EARTH_AND_THE_SOLAR_SYST.ES_STRUCTURE.M_ES_CRUST_THICK', 'SOCI.G7.NATURA.EARTH_AND_THE_SOLAR_SYST.ES_STRUCTURE', 'Thinks the crust is the thickest layer.', '{"question":"Which is the thinnest layer of the earth?","wrong_answer":"The mantle","correct_answer":"The crust"}'::jsonb, 'The ground feels solid and deep to the child.', 'Offer "The mantle" next to the right answer and ask the question again in a new context.', 'Ask the child to compare an apple''s skin with its flesh.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.NATURA.EARTH_AND_THE_SOLAR_SYST.ES_ORIGIN_SIZE.M_ES_EARTH_CENTRE', 'SOCI.G7.NATURA.EARTH_AND_THE_SOLAR_SYST.ES_ORIGIN_SIZE', 'Thinks the earth is at the centre of the solar system.', '{"question":"What is at the centre of the solar system?","wrong_answer":"The earth","correct_answer":"The Sun"}'::jsonb, 'The sun appears to go round us.', 'Offer "The earth" next to the right answer and ask the question again in a new context.', 'Act it: one learner as the Sun in the middle, others as planets.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.NATURA.EARTH_AND_THE_SOLAR_SYST.ES_ORIGIN_SIZE.M_ES_EARTH_BIGGEST', 'SOCI.G7.NATURA.EARTH_AND_THE_SOLAR_SYST.ES_ORIGIN_SIZE', 'Thinks the earth is the biggest planet.', '{"question":"Is the earth the biggest planet?","wrong_answer":"Yes","correct_answer":"No, Jupiter is the biggest"}'::jsonb, 'The earth is the planet the child knows.', 'Offer "Yes" next to the right answer and ask the question again in a new context.', 'Show planets drawn to size.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.NATURA.EARTH_AND_THE_SOLAR_SYST.ES_MOTION.M_ES_LEAP_RANDOM', 'SOCI.G7.NATURA.EARTH_AND_THE_SOLAR_SYST.ES_MOTION', 'Does not know why there is a leap year.', '{"question":"Why is there a leap year every four years?","wrong_answer":"For no reason","correct_answer":"The earth takes about 365 and a quarter days to go round the Sun"}'::jsonb, 'The child knows the fact but not the reason.', 'Offer "For no reason" next to the right answer and ask the question again in a new context.', 'Add four quarter days to make one extra day.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.NATURA.EARTH_AND_THE_SOLAR_SYST.ES_MOTION.M_ES_ROTATION_YEAR', 'SOCI.G7.NATURA.EARTH_AND_THE_SOLAR_SYST.ES_MOTION', 'Mixes rotation with revolution: says one rotation takes a year.', '{"question":"How long does one rotation of the earth take?","wrong_answer":"One year","correct_answer":"About 24 hours"}'::jsonb, 'Both are movements of the earth.', 'Offer "One year" next to the right answer and ask the question again in a new context.', 'Spin a ball (rotation) and walk it round a lamp (revolution).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.NATURA.EARTH_AND_THE_SOLAR_SYST.ES_STRUCTURE.M_ES_MAGMA_CORE', 'SOCI.G7.NATURA.EARTH_AND_THE_SOLAR_SYST.ES_STRUCTURE', 'Thinks magma comes from the core.', '{"question":"Where does the magma that comes out of volcanoes form?","wrong_answer":"In the inner core","correct_answer":"In the upper mantle"}'::jsonb, 'The child thinks the hottest place makes the lava.', 'Offer "In the inner core" next to the right answer and ask the question again in a new context.', 'Label the layers and show magma rising from the mantle.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.NATURA.EARTH_AND_THE_SOLAR_SYST.ES_STRUCTURE.M_ES_LAYER_ORDER', 'SOCI.G7.NATURA.EARTH_AND_THE_SOLAR_SYST.ES_STRUCTURE', 'Puts the layers in the wrong order, with the mantle outside the crust.', '{"question":"Put in order from the surface: core, crust, mantle.","wrong_answer":"mantle, crust, core","correct_answer":"crust, mantle, core"}'::jsonb, 'The child guesses from the words.', 'Offer "mantle, crust, core" next to the right answer and ask the question again in a new context.', 'Cut a hard-boiled egg: shell (crust), white (mantle), yolk (core).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.NATURA.WEATHER.WE_ELEMENTS.M_WE_TEMP_BAROMETER', 'SOCI.G7.NATURA.WEATHER.WE_ELEMENTS', 'Swaps the instruments, for example a barometer for temperature.', '{"question":"Which instrument measures air pressure?","wrong_answer":"The thermometer","correct_answer":"The barometer"}'::jsonb, 'The instruments are learnt as a list and the names are swapped.', 'Offer "The thermometer" next to the right answer and ask the question again in a new context.', 'Ask what a thermometer measures.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.NATURA.WEATHER.WE_ELEMENTS.M_WE_WEATHER_CLIMATE', 'SOCI.G7.NATURA.WEATHER.WE_ELEMENTS', 'Treats weather and climate as the same.', '{"question":"Which tells the climate of a place?","wrong_answer":"Today''s temperature","correct_answer":"The pattern of weather over many years"}'::jsonb, 'People use "weather" and "climate" the same way in everyday talk.', 'Offer "Today''s temperature" next to the right answer and ask the question again in a new context.', 'Ask whether one sunny day tells us Nairobi''s climate.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.NATURA.WEATHER.WE_SIGNIFICANCE.M_WE_RIVER_CROSS', 'SOCI.G7.NATURA.WEATHER.WE_SIGNIFICANCE', 'Thinks it is safe to cross a flooded river or shelter under a tree in a storm.', '{"question":"During lightning, where is it safe to be?","wrong_answer":"Under a tall tree","correct_answer":"Inside a building"}'::jsonb, 'A tree looks like shelter from rain, and the child does not know lightning strikes tall things.', 'Offer "Under a tall tree" next to the right answer and ask the question again in a new context.', 'Ask why tall trees attract lightning.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.NATURA.WEATHER.WE_SIGNIFICANCE.M_WE_FORECAST_USELESS', 'SOCI.G7.NATURA.WEATHER.WE_SIGNIFICANCE', 'Thinks a forecast is useless because it can be wrong sometimes.', '{"question":"Why do farmers listen to the forecast?","wrong_answer":"It is useless","correct_answer":"To plan planting and harvest"}'::jsonb, 'The child remembers one wrong forecast and generalises.', 'Offer "It is useless" next to the right answer and ask the question again in a new context.', 'Ask what a farmer does if heavy rain is coming at harvest.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.NATURA.WEATHER.WE_ELEMENTS.M_WE_SCREEN_SUN', 'SOCI.G7.NATURA.WEATHER.WE_ELEMENTS', 'Thinks the Stevenson screen is painted white and kept in the sun to warm the instruments.', '{"question":"Why is a Stevenson screen painted white?","wrong_answer":"To warm the instruments","correct_answer":"To reflect the sun so readings are of the air, not of direct sunshine"}'::jsonb, 'White is seen as a nice colour, not as reflecting heat.', 'Offer "To warm the instruments" next to the right answer and ask the question again in a new context.', 'Feel a white and a black cloth after an hour in the sun.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.NATURA.WEATHER.WE_ELEMENTS.M_WE_HYGRO_RAIN', 'SOCI.G7.NATURA.WEATHER.WE_ELEMENTS', 'Thinks a hygrometer measures rainfall.', '{"question":"What does a hygrometer measure?","wrong_answer":"Rainfall","correct_answer":"Humidity, the water vapour in the air"}'::jsonb, 'Both are about water.', 'Offer "Rainfall" next to the right answer and ask the question again in a new context.', 'Match each instrument to its element on cards.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.NATURA.WEATHER.WE_SIGNIFICANCE.M_WE_HEAT_NO_RISK', 'SOCI.G7.NATURA.WEATHER.WE_SIGNIFICANCE', 'Thinks great heat has no danger if you stay in the shade.', '{"question":"What should you do in very hot weather?","wrong_answer":"Nothing special","correct_answer":"Drink water, cover up and rest in the shade"}'::jsonb, 'The child thinks only of comfort.', 'Offer "Nothing special" next to the right answer and ask the question again in a new context.', 'Talk about signs of heat illness.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.NATURA.WEATHER.WE_SIGNIFICANCE.M_WE_TRANSPORT_NONE', 'SOCI.G7.NATURA.WEATHER.WE_SIGNIFICANCE', 'Does not see weather affecting transport.', '{"question":"How can heavy rain affect transport?","wrong_answer":"It cannot","correct_answer":"Roads flood or become muddy and flights may be delayed"}'::jsonb, 'The child does not connect the two.', 'Offer "It cannot" next to the right answer and ask the question again in a new context.', 'Recall roads cut off in the long rains.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.NATURA.FIELDWORK.FW_METHODS.M_FW_QUESTION_OBS', 'SOCI.G7.NATURA.FIELDWORK.FW_METHODS', 'Mixes up the methods, such as observation and interview.', '{"question":"Counting the number of vehicles passing a gate is which method?","wrong_answer":"Interview","correct_answer":"Observation"}'::jsonb, 'The child has not yet sorted methods by whether you ask or watch.', 'Offer "Interview" next to the right answer and ask the question again in a new context.', 'Ask: do we ask someone or do we watch and count?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.NATURA.FIELDWORK.FW_METHODS.M_FW_OPINION_OBS', 'SOCI.G7.NATURA.FIELDWORK.FW_METHODS', 'Uses observation for people''s opinions.', '{"question":"Which method best finds out what drivers think of the road?","wrong_answer":"Observation","correct_answer":"An interview or questionnaire"}'::jsonb, 'The child thinks watching people tells you what they think.', 'Offer "Observation" next to the right answer and ask the question again in a new context.', 'Ask: can you see an opinion?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.NATURA.FIELDWORK.FW_CHALLENGES.M_FW_IGNORE_RISK', 'SOCI.G7.NATURA.FIELDWORK.FW_CHALLENGES', 'Ignores safety, such as crossing a road without care.', '{"question":"What is the safe way to study a busy road?","wrong_answer":"Stand in the road","correct_answer":"Stay on the verge with a teacher"}'::jsonb, 'The child focuses on the task and forgets the danger around it.', 'Offer "Stand in the road" next to the right answer and ask the question again in a new context.', 'Ask where a driver can see a learner clearly.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.NATURA.FIELDWORK.FW_CHALLENGES.M_FW_NO_PERMISSION', 'SOCI.G7.NATURA.FIELDWORK.FW_CHALLENGES', 'Skips permission and explanation.', '{"question":"What should you do before interviewing a shop owner?","wrong_answer":"Start questions at once","correct_answer":"Greet, explain and ask permission"}'::jsonb, 'The child is eager to start and does not think of the other person''s time.', 'Offer "Start questions at once" next to the right answer and ask the question again in a new context.', 'Ask how the owner might feel if a stranger shouted questions.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.NATURA.FIELDWORK.FW_ANALYSIS.M_FW_MEAN_MEDIAN', 'SOCI.G7.NATURA.FIELDWORK.FW_ANALYSIS', 'Takes the middle number without ordering, or the biggest as the mean.', '{"question":"Find the median of 7, 2, 9, 4, 5.","wrong_answer":"9","correct_answer":"5"}'::jsonb, 'The child takes "middle" as the middle of the list as written.', 'Offer "9" next to the right answer and ask the question again in a new context.', 'Ask the child to write the numbers in order first.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.NATURA.FIELDWORK.FW_ANALYSIS.M_FW_MODE_MEAN', 'SOCI.G7.NATURA.FIELDWORK.FW_ANALYSIS', 'Mixes up mean, median and mode.', '{"question":"Which value occurs most often?","wrong_answer":"The mean","correct_answer":"The mode"}'::jsonb, 'The three words are new and learnt together.', 'Offer "The mean" next to the right answer and ask the question again in a new context.', 'Ask the child to count how many times each value appears.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.NATURA.FIELDWORK.FW_METHODS.M_FW_QUESTIONNAIRE_ORAL', 'SOCI.G7.NATURA.FIELDWORK.FW_METHODS', 'Thinks a questionnaire is asked aloud like an interview.', '{"question":"What is a questionnaire?","wrong_answer":"Questions asked aloud face to face","correct_answer":"A set of written questions people answer"}'::jsonb, 'Both involve questions.', 'Offer "Questions asked aloud face to face" next to the right answer and ask the question again in a new context.', 'Show a printed questionnaire and act an interview.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.NATURA.FIELDWORK.FW_METHODS.M_FW_ONE_METHOD', 'SOCI.G7.NATURA.FIELDWORK.FW_METHODS', 'Thinks one method is enough for every task.', '{"question":"You want to count vehicles and know what drivers think. How many methods?","wrong_answer":"One method","correct_answer":"Two: observation for counting and interviews for opinions"}'::jsonb, 'The child does not match method to question.', 'Offer "One method" next to the right answer and ask the question again in a new context.', 'Split the task into two questions.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.NATURA.FIELDWORK.FW_CHALLENGES.M_FW_WEATHER_IGNORE', 'SOCI.G7.NATURA.FIELDWORK.FW_CHALLENGES', 'Does not plan for bad weather in fieldwork.', '{"question":"How do you plan for rain on a fieldwork day?","wrong_answer":"Do nothing","correct_answer":"Check the forecast and carry rain gear or change the date"}'::jsonb, 'The child does not think ahead.', 'Offer "Do nothing" next to the right answer and ask the question again in a new context.', 'Make a fieldwork checklist.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.NATURA.FIELDWORK.FW_CHALLENGES.M_FW_MONEY_NONE', 'SOCI.G7.NATURA.FIELDWORK.FW_CHALLENGES', 'Does not see cost as a fieldwork challenge.', '{"question":"How can a class meet the cost of a fieldwork trip?","wrong_answer":"There is no cost","correct_answer":"Plan a small budget and choose a near site"}'::jsonb, 'The child does not think of transport costs.', 'Offer "There is no cost" next to the right answer and ask the question again in a new context.', 'List the costs of a trip.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.NATURA.FIELDWORK.FW_ANALYSIS.M_FW_MEAN_NO_DIVIDE', 'SOCI.G7.NATURA.FIELDWORK.FW_ANALYSIS', 'Adds the values for the mean and forgets to divide.', '{"question":"Find the mean of 4, 6 and 8.","wrong_answer":"18","correct_answer":"6"}'::jsonb, 'The child stops after adding.', 'Offer "18" next to the right answer and ask the question again in a new context.', 'Share 18 beans among 3 learners.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.NATURA.FIELDWORK.FW_ANALYSIS.M_FW_PIE_ANY', 'SOCI.G7.NATURA.FIELDWORK.FW_ANALYSIS', 'Picks a pie chart for data over time.', '{"question":"Which graph best shows rainfall each month for a year?","wrong_answer":"A pie chart","correct_answer":"A bar graph"}'::jsonb, 'The child picks the most colourful graph.', 'Offer "A pie chart" next to the right answer and ask the question again in a new context.', 'Draw both and ask which shows the change month by month.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.POLITI.POLITICAL_DEVELOPMENT_IN.PD_SCRAMBLE.M_PD_ASK_AFRICANS', 'SOCI.G7.POLITI.POLITICAL_DEVELOPMENT_IN.PD_SCRAMBLE', 'Thinks Africans invited the Europeans to divide Africa.', '{"question":"Who decided to divide Africa at Berlin?","wrong_answer":"African leaders","correct_answer":"European powers"}'::jsonb, 'Some treaties were signed by African leaders, so the child thinks they agreed to everything.', 'Offer "African leaders" next to the right answer and ask the question again in a new context.', 'Ask who was at the table in Berlin.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.POLITI.POLITICAL_DEVELOPMENT_IN.PD_SCRAMBLE.M_PD_MISSION_ONLY', 'SOCI.G7.POLITI.POLITICAL_DEVELOPMENT_IN.PD_SCRAMBLE', 'Thinks missionaries had no part in colonisation or only did harm.', '{"question":"What was a role of missionaries in the scramble?","wrong_answer":"None at all","correct_answer":"They opened stations and schools, and often prepared the way"}'::jsonb, 'The child knows missionaries for schools and churches and does not link them with colonisation.', 'Offer "None at all" next to the right answer and ask the question again in a new context.', 'Ask what a mission station gave local people and what it gave the colonial power.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.POLITI.POLITICAL_DEVELOPMENT_IN.PD_BERLIN.M_PD_BERLIN_DIVIDED', 'SOCI.G7.POLITI.POLITICAL_DEVELOPMENT_IN.PD_BERLIN', 'Believes the whole of Africa was drawn up at the Berlin Conference.', '{"question":"What did the Berlin Conference decide?","wrong_answer":"Exact borders for every African country","correct_answer":"Rules for claiming African land"}'::jsonb, 'The phrase "partition at Berlin" suggests lines were drawn there.', 'Offer "Exact borders for every African country" next to the right answer and ask the question again in a new context.', 'Ask whether anyone had surveyed Africa at the time.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.POLITI.POLITICAL_DEVELOPMENT_IN.PD_BERLIN.M_PD_BERLIN_AFRICANS', 'SOCI.G7.POLITI.POLITICAL_DEVELOPMENT_IN.PD_BERLIN', 'Thinks African chiefs attended the Conference.', '{"question":"Who attended the Berlin Conference?","wrong_answer":"African chiefs and Europeans","correct_answer":"European powers, with the United States as observer"}'::jsonb, 'The child assumes a meeting about Africa would include Africans.', 'Offer "African chiefs and Europeans" next to the right answer and ask the question again in a new context.', 'Ask the child what that means for African views.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.POLITI.POLITICAL_DEVELOPMENT_IN.PD_IMPLICATIONS.M_PD_ALL_GOOD', 'SOCI.G7.POLITI.POLITICAL_DEVELOPMENT_IN.PD_IMPLICATIONS', 'Says colonial rule brought only benefits, or only harm.', '{"question":"Which is a harm of colonial rule?","wrong_answer":"Roads for the colonial economy","correct_answer":"Loss of land and independence"}'::jsonb, 'The child sees roads and schools today and credits all of it to colonial rule.', 'Offer "Roads for the colonial economy" next to the right answer and ask the question again in a new context.', 'Ask who the railways were built to serve.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.POLITI.POLITICAL_DEVELOPMENT_IN.PD_IMPLICATIONS.M_PD_BORDERS_FAIR', 'SOCI.G7.POLITI.POLITICAL_DEVELOPMENT_IN.PD_IMPLICATIONS', 'Thinks colonial borders followed the homes of peoples.', '{"question":"What did colonial borders do to communities?","wrong_answer":"Kept each community together","correct_answer":"Split some communities and joined others"}'::jsonb, 'The child assumes borders follow natural groups of people.', 'Offer "Kept each community together" next to the right answer and ask the question again in a new context.', 'Ask which communities live in two countries today.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.POLITI.POLITICAL_DEVELOPMENT_IN.PD_NEO.M_PD_NEO_SAME', 'SOCI.G7.POLITI.POLITICAL_DEVELOPMENT_IN.PD_NEO', 'Thinks neo-colonialism is the same as colonialism.', '{"question":"What is neo-colonialism?","wrong_answer":"Direct rule by a foreign army","correct_answer":"Control of a free country through money, trade and debt"}'::jsonb, 'The two words share "colonialism".', 'Offer "Direct rule by a foreign army" next to the right answer and ask the question again in a new context.', 'Ask who runs the country when it owes a great debt.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.POLITI.POLITICAL_DEVELOPMENT_IN.PD_NEO.M_PD_NEO_CORRUPT', 'SOCI.G7.POLITI.POLITICAL_DEVELOPMENT_IN.PD_NEO', 'Thinks corruption helps a nation to end neo-colonialism.', '{"question":"Which helps to end neo-colonialism?","wrong_answer":"Taking bribes from foreign firms","correct_answer":"Honest, accountable leaders"}'::jsonb, 'Bribes bring money into the country, so the child thinks they help.', 'Offer "Taking bribes from foreign firms" next to the right answer and ask the question again in a new context.', 'Ask what bribes do to a country''s resources.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.POLITI.POLITICAL_DEVELOPMENT_IN.PD_SCRAMBLE.M_PD_EXPLORERS_TOURISTS', 'SOCI.G7.POLITI.POLITICAL_DEVELOPMENT_IN.PD_SCRAMBLE', 'Thinks European explorers came only as tourists.', '{"question":"What role did explorers play in the scramble?","wrong_answer":"They were only tourists","correct_answer":"They mapped routes and reported on resources"}'::jsonb, 'The child pictures explorers as travellers.', 'Offer "They were only tourists" next to the right answer and ask the question again in a new context.', 'Read a short explorer report about rivers and resources.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.POLITI.POLITICAL_DEVELOPMENT_IN.PD_SCRAMBLE.M_PD_REASON_HELP', 'SOCI.G7.POLITI.POLITICAL_DEVELOPMENT_IN.PD_SCRAMBLE', 'Thinks Europeans came only to help Africans.', '{"question":"Give an economic reason for the scramble.","wrong_answer":"To help Africans only","correct_answer":"To get raw materials and markets for European industries"}'::jsonb, 'Missions and schools are the face the child sees.', 'Offer "To help Africans only" next to the right answer and ask the question again in a new context.', 'List what Europe needed: cotton, rubber, minerals, markets.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.POLITI.POLITICAL_DEVELOPMENT_IN.PD_BERLIN.M_PD_BERLIN_KENYA', 'SOCI.G7.POLITI.POLITICAL_DEVELOPMENT_IN.PD_BERLIN', 'Thinks the Berlin Conference was held in Kenya or Africa.', '{"question":"Where was the conference to divide Africa held?","wrong_answer":"In Nairobi","correct_answer":"In Berlin, Germany"}'::jsonb, 'The child links the topic with the place.', 'Offer "In Nairobi" next to the right answer and ask the question again in a new context.', 'Show Berlin on a world map.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.POLITI.POLITICAL_DEVELOPMENT_IN.PD_BERLIN.M_PD_OCCUPATION_MEANING', 'SOCI.G7.POLITI.POLITICAL_DEVELOPMENT_IN.PD_BERLIN', 'Thinks effective occupation meant only drawing a claim on a map.', '{"question":"What did \"effective occupation\" require?","wrong_answer":"Drawing a line on a map","correct_answer":"Having officials, soldiers or trade in the area to show control"}'::jsonb, 'Claims are pictured as lines on maps.', 'Offer "Drawing a line on a map" next to the right answer and ask the question again in a new context.', 'Contrast a line on paper with a fort and officials on the ground.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.POLITI.POLITICAL_DEVELOPMENT_IN.PD_IMPLICATIONS.M_PD_LAND_KEPT', 'SOCI.G7.POLITI.POLITICAL_DEVELOPMENT_IN.PD_IMPLICATIONS', 'Thinks Africans kept all their land under colonial rule.', '{"question":"What happened to much African land in the Kenyan highlands under colonial rule?","wrong_answer":"Africans kept it","correct_answer":"It was taken for European settlers"}'::jsonb, 'The child does not know about the White Highlands.', 'Offer "Africans kept it" next to the right answer and ask the question again in a new context.', 'Show a map of the settler areas.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.POLITI.POLITICAL_DEVELOPMENT_IN.PD_IMPLICATIONS.M_PD_CASH_CROP_FOOD', 'SOCI.G7.POLITI.POLITICAL_DEVELOPMENT_IN.PD_IMPLICATIONS', 'Thinks cash crops were grown to feed Africans.', '{"question":"Why were cash crops such as coffee grown in colonial times?","wrong_answer":"To feed Africans","correct_answer":"To sell and supply European industries"}'::jsonb, 'Crops are linked with food.', 'Offer "To feed Africans" next to the right answer and ask the question again in a new context.', 'Ask who drank the coffee.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.POLITI.POLITICAL_DEVELOPMENT_IN.PD_NEO.M_PD_TRADE_BAD', 'SOCI.G7.POLITI.POLITICAL_DEVELOPMENT_IN.PD_NEO', 'Thinks any trade with a rich country is neo-colonialism.', '{"question":"Is selling tea to Britain at a fair price neo-colonialism?","wrong_answer":"Yes, all trade with them is","correct_answer":"No, neo-colonialism is control through unfair debt, trade or politics"}'::jsonb, 'The child stretches the idea to all contact.', 'Offer "Yes, all trade with them is" next to the right answer and ask the question again in a new context.', 'Compare a fair deal with a deal forced by debt.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.POLITI.POLITICAL_DEVELOPMENT_IN.PD_NEO.M_PD_LOAN_FREE', 'SOCI.G7.POLITI.POLITICAL_DEVELOPMENT_IN.PD_NEO', 'Thinks foreign loans have no conditions or risks.', '{"question":"How can large foreign loans lead to neo-colonialism?","wrong_answer":"They cannot","correct_answer":"Debt can let the lender influence the borrower''s decisions"}'::jsonb, 'Loans are seen as free help.', 'Offer "They cannot" next to the right answer and ask the question again in a new context.', 'Act a lender asking for favours from a borrower who cannot pay.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.POLITI.THE_CONSTITUTION_OF_KENY.CK_IMPORTANCE.M_CK_AUTHORITY', 'SOCI.G7.POLITI.THE_CONSTITUTION_OF_KENY.CK_IMPORTANCE', 'Says the President is above the Constitution.', '{"question":"Which is the supreme law of Kenya?","wrong_answer":"The President''s word","correct_answer":"The Constitution"}'::jsonb, 'The President is the most powerful person the child knows of.', 'Offer "The President''s word" next to the right answer and ask the question again in a new context.', 'Ask who must obey the Constitution.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.POLITI.THE_CONSTITUTION_OF_KENY.CK_IMPORTANCE.M_CK_DATE_MIX', 'SOCI.G7.POLITI.THE_CONSTITUTION_OF_KENY.CK_IMPORTANCE', 'Mixes up independence and the new Constitution.', '{"question":"When was the current Constitution promulgated?","wrong_answer":"12 December 1963","correct_answer":"27 August 2010"}'::jsonb, 'Both are big national dates and the child remembers 1963 best.', 'Offer "12 December 1963" next to the right answer and ask the question again in a new context.', 'Ask what happened on 12 December 1963.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.POLITI.THE_CONSTITUTION_OF_KENY.CK_UPHOLD.M_CK_BRIBE_OK', 'SOCI.G7.POLITI.THE_CONSTITUTION_OF_KENY.CK_UPHOLD', 'Thinks a small bribe does not hurt the Constitution.', '{"question":"Which action breaks the Constitution''s values?","wrong_answer":"Voting","correct_answer":"Giving a bribe to a police officer"}'::jsonb, 'The child sees small bribes treated as normal around them.', 'Offer "Voting" next to the right answer and ask the question again in a new context.', 'Ask what integrity means.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.POLITI.THE_CONSTITUTION_OF_KENY.CK_UPHOLD.M_CK_ONLY_LEADERS', 'SOCI.G7.POLITI.THE_CONSTITUTION_OF_KENY.CK_UPHOLD', 'Believes only leaders must protect the Constitution.', '{"question":"Who must protect the Constitution?","wrong_answer":"Only leaders","correct_answer":"Every citizen"}'::jsonb, 'The Constitution seems to be about government, so the child thinks leaders alone keep it.', 'Offer "Only leaders" next to the right answer and ask the question again in a new context.', 'Ask what a learner can do.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.POLITI.THE_CONSTITUTION_OF_KENY.CK_VALUES.M_CK_VALUE_MIX', 'SOCI.G7.POLITI.THE_CONSTITUTION_OF_KENY.CK_VALUES', 'Gives a value that is not a national value, such as wealth.', '{"question":"Which is a national value in the Constitution?","wrong_answer":"Wealth","correct_answer":"Integrity"}'::jsonb, 'The child picks something people value in daily life rather than a value named in the Constitution.', 'Offer "Wealth" next to the right answer and ask the question again in a new context.', 'Ask for a value from the list in Article 10.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.POLITI.THE_CONSTITUTION_OF_KENY.CK_VALUES.M_CK_PATRIOT_BLIND', 'SOCI.G7.POLITI.THE_CONSTITUTION_OF_KENY.CK_VALUES', 'Thinks patriotism means saying other countries are bad.', '{"question":"What is patriotism?","wrong_answer":"Saying other countries are bad","correct_answer":"Love and loyalty to your country"}'::jsonb, 'Loving your own country is mixed with looking down on others.', 'Offer "Saying other countries are bad" next to the right answer and ask the question again in a new context.', 'Ask how a good citizen can love Kenya and respect Uganda.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.POLITI.THE_CONSTITUTION_OF_KENY.CK_IMPORTANCE.M_CK_FIRST_CONSTITUTION', 'SOCI.G7.POLITI.THE_CONSTITUTION_OF_KENY.CK_IMPORTANCE', 'Thinks the 2010 Constitution was Kenya''s first constitution.', '{"question":"Was the 2010 Constitution Kenya''s first?","wrong_answer":"Yes","correct_answer":"No, Kenya had an independence constitution in 1963"}'::jsonb, 'The 2010 Constitution is the one talked about.', 'Offer "Yes" next to the right answer and ask the question again in a new context.', 'Put 1963 and 2010 on a timeline.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.POLITI.THE_CONSTITUTION_OF_KENY.CK_IMPORTANCE.M_CK_RIGHTS_NONE', 'SOCI.G7.POLITI.THE_CONSTITUTION_OF_KENY.CK_IMPORTANCE', 'Does not know the Constitution contains a Bill of Rights.', '{"question":"Where are the rights of every Kenyan written?","wrong_answer":"Nowhere","correct_answer":"In the Bill of Rights in the Constitution"}'::jsonb, 'The child has not seen the chapters.', 'Offer "Nowhere" next to the right answer and ask the question again in a new context.', 'Show the chapter list of the Constitution.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.POLITI.THE_CONSTITUTION_OF_KENY.CK_UPHOLD.M_CK_COURT_IGNORE', 'SOCI.G7.POLITI.THE_CONSTITUTION_OF_KENY.CK_UPHOLD', 'Thinks ignoring a court order is fine if you disagree with it.', '{"question":"Should a citizen obey a court order they disagree with?","wrong_answer":"No, ignore it","correct_answer":"Yes, obey it and appeal through the courts if needed"}'::jsonb, 'Disagreeing feels like a reason not to obey.', 'Offer "No, ignore it" next to the right answer and ask the question again in a new context.', 'Explain appeal as the lawful way to disagree.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.POLITI.THE_CONSTITUTION_OF_KENY.CK_UPHOLD.M_CK_PARTICIPATION_NONE', 'SOCI.G7.POLITI.THE_CONSTITUTION_OF_KENY.CK_UPHOLD', 'Does not see taking part in public meetings as upholding the Constitution.', '{"question":"How does attending a public meeting on the county budget uphold the Constitution?","wrong_answer":"It does not","correct_answer":"The Constitution gives people the right to take part in decisions"}'::jsonb, 'The child thinks only voting counts.', 'Offer "It does not" next to the right answer and ask the question again in a new context.', 'Show the notice of a public participation forum.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.POLITI.THE_CONSTITUTION_OF_KENY.CK_VALUES.M_CK_VALUE_ACTION', 'SOCI.G7.POLITI.THE_CONSTITUTION_OF_KENY.CK_VALUES', 'Cannot match a national value to an everyday action.', '{"question":"Sharing a desk fairly with a learner with a disability shows which national value?","wrong_answer":"Wealth","correct_answer":"Inclusiveness or equity"}'::jsonb, 'The values are memorised as a list.', 'Offer "Wealth" next to the right answer and ask the question again in a new context.', 'Act small situations and name the value.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.POLITI.THE_CONSTITUTION_OF_KENY.CK_VALUES.M_CK_DEVOLUTION_NOT_VALUE', 'SOCI.G7.POLITI.THE_CONSTITUTION_OF_KENY.CK_VALUES', 'Does not know sharing and devolution of power is a national value.', '{"question":"Is devolution of power a national value in Article 10?","wrong_answer":"No","correct_answer":"Yes"}'::jsonb, 'Devolution is seen as government structure only.', 'Offer "No" next to the right answer and ask the question again in a new context.', 'Read Article 10 aloud.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.POLITI.HUMAN_RIGHTS.HR_CLASSIFY.M_HR_VOTE_SOCIAL', 'SOCI.G7.POLITI.HUMAN_RIGHTS.HR_CLASSIFY', 'Puts the right to vote among social rights and the right to education among political ones.', '{"question":"Which is a civil and political right?","wrong_answer":"The right to education","correct_answer":"The right to vote"}'::jsonb, 'Voting is done by society, so the child calls it social.', 'Offer "The right to education" next to the right answer and ask the question again in a new context.', 'Ask which rights relate to elections.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.POLITI.HUMAN_RIGHTS.HR_CLASSIFY.M_HR_UDHR_KENYA', 'SOCI.G7.POLITI.HUMAN_RIGHTS.HR_CLASSIFY', 'Mixes up the instruments, for example the African Charter with the UN Declaration.', '{"question":"Which instrument was adopted by the United Nations in 1948?","wrong_answer":"The African Charter","correct_answer":"The Universal Declaration of Human Rights"}'::jsonb, 'The instruments have long similar names.', 'Offer "The African Charter" next to the right answer and ask the question again in a new context.', 'Ask which body began with the word African.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.POLITI.HUMAN_RIGHTS.HR_EQUITY.M_HR_EQUAL_EQUITY', 'SOCI.G7.POLITI.HUMAN_RIGHTS.HR_EQUITY', 'Treats equality and equity as the same.', '{"question":"What is equity?","wrong_answer":"Everyone gets exactly the same","correct_answer":"Everyone gets what is fair for their need"}'::jsonb, 'The words look alike and both are about fairness.', 'Offer "Everyone gets exactly the same" next to the right answer and ask the question again in a new context.', 'Ask what a learner who cannot see the board needs.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.POLITI.HUMAN_RIGHTS.HR_EQUITY.M_HR_EARNED', 'SOCI.G7.POLITI.HUMAN_RIGHTS.HR_EQUITY', 'Thinks rights are earned by good behaviour and can be taken away.', '{"question":"Can human rights be taken away?","wrong_answer":"Yes, if a person is naughty","correct_answer":"No, they belong to everyone"}'::jsonb, 'At school, privileges are earned and lost, and the child applies this to rights.', 'Offer "Yes, if a person is naughty" next to the right answer and ask the question again in a new context.', 'Ask if a child who breaks a rule loses the right to food.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.POLITI.HUMAN_RIGHTS.HR_ACTION.M_HR_JOIN_TEASE', 'SOCI.G7.POLITI.HUMAN_RIGHTS.HR_ACTION', 'Joins in teasing a classmate with a disability.', '{"question":"A classmate walks with a stick. Others laugh at him. What should you do?","wrong_answer":"Laugh too","correct_answer":"Stand by him and tell the others it is wrong"}'::jsonb, 'The child fears being left out if they do not join the group.', 'Offer "Laugh too" next to the right answer and ask the question again in a new context.', 'Ask how the classmate feels.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.POLITI.HUMAN_RIGHTS.HR_ACTION.M_HR_NOT_MY_BUSINESS', 'SOCI.G7.POLITI.HUMAN_RIGHTS.HR_ACTION', 'Thinks protecting rights is only for the police and the government.', '{"question":"Who can protect human rights?","wrong_answer":"Only the police","correct_answer":"Everyone"}'::jsonb, 'Rights are taught with courts and police, so the child thinks it is their job.', 'Offer "Only the police" next to the right answer and ask the question again in a new context.', 'Ask what a learner can do in class.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.POLITI.HUMAN_RIGHTS.HR_CLASSIFY.M_HR_GROUP_RIGHTS', 'SOCI.G7.POLITI.HUMAN_RIGHTS.HR_CLASSIFY', 'Does not know group or peoples'' rights such as a clean environment.', '{"question":"Which group does the right to a clean environment belong to?","wrong_answer":"Civil and political","correct_answer":"Group or peoples'' rights"}'::jsonb, 'The child knows only two groups.', 'Offer "Civil and political" next to the right answer and ask the question again in a new context.', 'Add a third column to the sort.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.POLITI.HUMAN_RIGHTS.HR_CLASSIFY.M_HR_CHAPTER_FOUR', 'SOCI.G7.POLITI.HUMAN_RIGHTS.HR_CLASSIFY', 'Does not know the Bill of Rights is Chapter Four of the Constitution.', '{"question":"Which chapter of the Constitution of Kenya is the Bill of Rights?","wrong_answer":"Chapter One","correct_answer":"Chapter Four"}'::jsonb, 'Chapter numbers are not memorable.', 'Offer "Chapter One" next to the right answer and ask the question again in a new context.', 'Show the chapter list.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.POLITI.HUMAN_RIGHTS.HR_EQUITY.M_HR_INALIENABLE', 'SOCI.G7.POLITI.HUMAN_RIGHTS.HR_EQUITY', 'Thinks inalienable means only for citizens.', '{"question":"What does \"inalienable\" mean?","wrong_answer":"Only for citizens","correct_answer":"Cannot be taken away"}'::jsonb, 'The word "alien" suggests foreigners.', 'Offer "Only for citizens" next to the right answer and ask the question again in a new context.', 'Break the word: in (not) + alienable (able to be taken).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.POLITI.HUMAN_RIGHTS.HR_EQUITY.M_HR_DISCRIM_KIND', 'SOCI.G7.POLITI.HUMAN_RIGHTS.HR_EQUITY', 'Thinks discrimination only means insults, not unfair treatment.', '{"question":"A school refuses a learner because of her religion. Is this discrimination?","wrong_answer":"No, nobody insulted her","correct_answer":"Yes, it is unfair treatment because of who she is"}'::jsonb, 'Discrimination is pictured as name-calling.', 'Offer "No, nobody insulted her" next to the right answer and ask the question again in a new context.', 'Discuss refusals and exclusions as discrimination.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.POLITI.HUMAN_RIGHTS.HR_ACTION.M_HR_EXCLUDE_GAME', 'SOCI.G7.POLITI.HUMAN_RIGHTS.HR_ACTION', 'Thinks leaving a learner out of games because they are slow is fair.', '{"question":"Is it fair to leave a slow runner out of every game?","wrong_answer":"Yes, to win","correct_answer":"No, include everyone and adjust the game"}'::jsonb, 'Winning feels more important.', 'Offer "Yes, to win" next to the right answer and ask the question again in a new context.', 'Play a game where everyone has a role.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.POLITI.HUMAN_RIGHTS.HR_ACTION.M_HR_REPORT_SNITCH', 'SOCI.G7.POLITI.HUMAN_RIGHTS.HR_ACTION', 'Thinks reporting abuse of a classmate is "snitching".', '{"question":"You learn a classmate is being abused. What should you do?","wrong_answer":"Say nothing, it is snitching","correct_answer":"Tell a trusted adult"}'::jsonb, 'The child fears being seen as a telltale.', 'Offer "Say nothing, it is snitching" next to the right answer and ask the question again in a new context.', 'Separate telling to get someone in trouble from telling to keep someone safe.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.POLITI.AFRICAN_DIASPORAS.AD_FACTORS.M_AD_ALL_VOLUNTARY', 'SOCI.G7.POLITI.AFRICAN_DIASPORAS.AD_FACTORS', 'Believes all Africans abroad went there by choice.', '{"question":"Which factor brought many Africans to the Americas?","wrong_answer":"Voluntary holidays","correct_answer":"The forced slave trade"}'::jsonb, 'Today many people travel abroad by choice, so the child thinks it was always so.', 'Offer "Voluntary holidays" next to the right answer and ask the question again in a new context.', 'Ask whether captives chose to board the ships.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.POLITI.AFRICAN_DIASPORAS.AD_FACTORS.M_AD_DIASPORA_WORD', 'SOCI.G7.POLITI.AFRICAN_DIASPORAS.AD_FACTORS', 'Thinks diaspora means the homeland.', '{"question":"What is a diaspora?","wrong_answer":"The homeland of a people","correct_answer":"A people living away from their homeland"}'::jsonb, 'The word is new and linked to the homeland in the lesson.', 'Offer "The homeland of a people" next to the right answer and ask the question again in a new context.', 'Ask where the diaspora lives.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.POLITI.AFRICAN_DIASPORAS.AD_LOCATE.M_AD_NO_AMERICAS', 'SOCI.G7.POLITI.AFRICAN_DIASPORAS.AD_LOCATE', 'Leaves the Americas out when naming where the diaspora lived.', '{"question":"Which region held a large African diaspora by 1960?","wrong_answer":"Only Asia","correct_answer":"The Americas"}'::jsonb, 'The child knows Africans in Arabia from the Indian Ocean lesson and stops there.', 'Offer "Only Asia" next to the right answer and ask the question again in a new context.', 'Ask which countries are named for the Caribbean.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.POLITI.AFRICAN_DIASPORAS.AD_LOCATE.M_AD_JAMAICA_ASIA', 'SOCI.G7.POLITI.AFRICAN_DIASPORAS.AD_LOCATE', 'Puts Jamaica or Brazil on the wrong continent.', '{"question":"In which region is Jamaica?","wrong_answer":"Asia","correct_answer":"The Caribbean, in the Americas"}'::jsonb, 'The child has not placed Caribbean islands on a world map.', 'Offer "Asia" next to the right answer and ask the question again in a new context.', 'Ask which ocean lies around Jamaica.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.POLITI.AFRICAN_DIASPORAS.AD_ROLE.M_AD_NO_ROLE', 'SOCI.G7.POLITI.AFRICAN_DIASPORAS.AD_ROLE', 'Says the diaspora played no part in African independence.', '{"question":"How did the diaspora help African independence?","wrong_answer":"It did not help","correct_answer":"It supported the Pan-African movement and wrote about freedom"}'::jsonb, 'Independence stories focus on leaders inside Africa.', 'Offer "It did not help" next to the right answer and ask the question again in a new context.', 'Ask who organised Pan-African congresses.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.POLITI.AFRICAN_DIASPORAS.AD_ROLE.M_AD_PAN_MEANING', 'SOCI.G7.POLITI.AFRICAN_DIASPORAS.AD_ROLE', 'Mixes up Pan-Africanism with a trade bloc or a single country.', '{"question":"What is Pan-Africanism?","wrong_answer":"A trading company","correct_answer":"The idea that African people should unite"}'::jsonb, 'Pan-African sounds like the name of an organisation.', 'Offer "A trading company" next to the right answer and ask the question again in a new context.', 'Ask what pan means.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.POLITI.AFRICAN_DIASPORAS.AD_FACTORS.M_AD_ONLY_SLAVERY', 'SOCI.G7.POLITI.AFRICAN_DIASPORAS.AD_FACTORS', 'Thinks the slave trade is the only reason Africans live abroad.', '{"question":"Give a reason Africans live abroad today besides the slave trade.","wrong_answer":"There is none","correct_answer":"Work, study or fleeing war"}'::jsonb, 'The slave trade is the reason taught first.', 'Offer "There is none" next to the right answer and ask the question again in a new context.', 'List reasons people move today.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.POLITI.AFRICAN_DIASPORAS.AD_FACTORS.M_AD_INDIAN_NONE', 'SOCI.G7.POLITI.AFRICAN_DIASPORAS.AD_FACTORS', 'Forgets that the Indian Ocean trade also created a diaspora.', '{"question":"Which trade took Africans to Arabia and India?","wrong_answer":"Only the Atlantic trade","correct_answer":"The Indian Ocean slave trade"}'::jsonb, 'The Atlantic trade is better known.', 'Offer "Only the Atlantic trade" next to the right answer and ask the question again in a new context.', 'Recall the Indian Ocean routes from the slavery lesson.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.POLITI.AFRICAN_DIASPORAS.AD_LOCATE.M_AD_BRAZIL_AFRICA', 'SOCI.G7.POLITI.AFRICAN_DIASPORAS.AD_LOCATE', 'Places Brazil in Africa.', '{"question":"In which continent is Brazil?","wrong_answer":"Africa","correct_answer":"South America"}'::jsonb, 'The child has heard of Brazil''s large African diaspora.', 'Offer "Africa" next to the right answer and ask the question again in a new context.', 'Find Brazil on a world map.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.POLITI.AFRICAN_DIASPORAS.AD_LOCATE.M_AD_EUROPE_NONE', 'SOCI.G7.POLITI.AFRICAN_DIASPORAS.AD_LOCATE', 'Thinks no African diaspora lived in Europe by 1960.', '{"question":"Did African diasporas live in Europe by 1960?","wrong_answer":"No","correct_answer":"Yes, in Britain and France"}'::jsonb, 'The child links the diaspora only with slavery in the Americas.', 'Offer "No" next to the right answer and ask the question again in a new context.', 'Name the Manchester Pan-African Congress of 1945.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.POLITI.AFRICAN_DIASPORAS.AD_ROLE.M_AD_NKRUMAH_DIASPORA', 'SOCI.G7.POLITI.AFRICAN_DIASPORAS.AD_ROLE', 'Thinks Kwame Nkrumah was born in the Americas.', '{"question":"Where was Kwame Nkrumah from?","wrong_answer":"The Americas","correct_answer":"Ghana (the Gold Coast)"}'::jsonb, 'He is named with diaspora leaders.', 'Offer "The Americas" next to the right answer and ask the question again in a new context.', 'Sort leaders: from the diaspora, from Africa.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.POLITI.AFRICAN_DIASPORAS.AD_ROLE.M_AD_CONGRESS_TRADE', 'SOCI.G7.POLITI.AFRICAN_DIASPORAS.AD_ROLE', 'Thinks the Pan-African congresses were trade fairs.', '{"question":"What were the Pan-African congresses?","wrong_answer":"Trade fairs","correct_answer":"Meetings that called for African freedom and unity"}'::jsonb, 'The child guesses from "congress".', 'Offer "Trade fairs" next to the right answer and ask the question again in a new context.', 'Read a short line from a congress resolution.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.POLITI.CITIZENSHIP.CZ_INTERDEP.M_CZ_SELF_SUFFICIENT', 'SOCI.G7.POLITI.CITIZENSHIP.CZ_INTERDEP', 'Believes a country can make everything it needs alone.', '{"question":"Why do countries trade?","wrong_answer":"Each makes everything it needs","correct_answer":"No country has every resource"}'::jsonb, 'The child thinks a strong country has everything.', 'Offer "Each makes everything it needs" next to the right answer and ask the question again in a new context.', 'Ask where Kenya''s oil comes from.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.POLITI.CITIZENSHIP.CZ_INTERDEP.M_CZ_INTERDEP_LOSS', 'SOCI.G7.POLITI.CITIZENSHIP.CZ_INTERDEP', 'Thinks depending on other countries always means being weak.', '{"question":"What does interdependence mean?","wrong_answer":"A country is weak and begging","correct_answer":"Countries need each other and both gain"}'::jsonb, 'Needing others feels like weakness to the child.', 'Offer "A country is weak and begging" next to the right answer and ask the question again in a new context.', 'Ask who gains from Kenya''s tea.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.POLITI.CITIZENSHIP.CZ_GLOBAL.M_CZ_GLOBAL_ALL_GOOD', 'SOCI.G7.POLITI.CITIZENSHIP.CZ_GLOBAL', 'Thinks globalisation has only good effects.', '{"question":"Which is a bad effect of globalisation?","wrong_answer":"Cheaper goods","correct_answer":"Loss of local culture and firms"}'::jsonb, 'The child sees cheap phones and clothes and stops at the benefits.', 'Offer "Cheaper goods" next to the right answer and ask the question again in a new context.', 'Ask what happens to local shops when cheap imports flood in.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.POLITI.CITIZENSHIP.CZ_GLOBAL.M_CZ_GLOBAL_ONLINE', 'SOCI.G7.POLITI.CITIZENSHIP.CZ_GLOBAL', 'Thinks globalisation means only the internet.', '{"question":"What is globalisation?","wrong_answer":"Only using the internet","correct_answer":"The world becoming one connected place"}'::jsonb, 'The internet is the most visible part of globalisation for the child.', 'Offer "Only using the internet" next to the right answer and ask the question again in a new context.', 'Ask which other things link countries.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.POLITI.CITIZENSHIP.CZ_CITIZEN.M_CZ_LOYAL_LOSS', 'SOCI.G7.POLITI.CITIZENSHIP.CZ_CITIZEN', 'Thinks being a global citizen means giving up loyalty to Kenya.', '{"question":"Can a global citizen love Kenya?","wrong_answer":"No, he must give up his country","correct_answer":"Yes, he serves the world and still loves his country"}'::jsonb, 'The child thinks loyalty can only go one way.', 'Offer "No, he must give up his country" next to the right answer and ask the question again in a new context.', 'Ask what Kenyan peacekeepers do for the world.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.POLITI.CITIZENSHIP.CZ_CITIZEN.M_CZ_ONLY_RICH', 'SOCI.G7.POLITI.CITIZENSHIP.CZ_CITIZEN', 'Thinks only rich people can be global citizens.', '{"question":"Who can be a global citizen?","wrong_answer":"Only rich people who travel","correct_answer":"Anyone who cares for people and the world"}'::jsonb, 'Global citizens are pictured as people who fly abroad.', 'Offer "Only rich people who travel" next to the right answer and ask the question again in a new context.', 'Ask what a learner can do for the environment.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.POLITI.CITIZENSHIP.CZ_INTERDEP.M_CZ_UN_KENYA', 'SOCI.G7.POLITI.CITIZENSHIP.CZ_INTERDEP', 'Thinks the United Nations is a Kenyan body.', '{"question":"Is the United Nations a Kenyan body?","wrong_answer":"Yes, it has offices in Nairobi","correct_answer":"No, it is a world body of many countries"}'::jsonb, 'The UN has offices at Gigiri in Nairobi.', 'Offer "Yes, it has offices in Nairobi" next to the right answer and ask the question again in a new context.', 'Show the flags of member countries.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.POLITI.CITIZENSHIP.CZ_INTERDEP.M_CZ_EXPORT_IMPORT_SWAP', 'SOCI.G7.POLITI.CITIZENSHIP.CZ_INTERDEP', 'Swaps exports and imports (says Kenya imports tea).', '{"question":"Does Kenya export or import tea?","wrong_answer":"Import","correct_answer":"Export"}'::jsonb, 'The two words sound alike.', 'Offer "Import" next to the right answer and ask the question again in a new context.', 'Ex = out, im = in: draw arrows.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.POLITI.CITIZENSHIP.CZ_GLOBAL.M_CZ_DISEASE_NONE', 'SOCI.G7.POLITI.CITIZENSHIP.CZ_GLOBAL', 'Does not see quick spread of disease as an effect of globalisation.', '{"question":"How can globalisation help a disease spread?","wrong_answer":"It cannot","correct_answer":"People travel fast between countries and carry it"}'::jsonb, 'The child links globalisation only with trade.', 'Offer "It cannot" next to the right answer and ask the question again in a new context.', 'Recall how COVID-19 spread around the world.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.POLITI.CITIZENSHIP.CZ_GLOBAL.M_CZ_LOCAL_FIRMS_GAIN', 'SOCI.G7.POLITI.CITIZENSHIP.CZ_GLOBAL', 'Thinks imports always help local firms.', '{"question":"How can cheap imports harm local firms?","wrong_answer":"They cannot","correct_answer":"Local firms may lose customers and close"}'::jsonb, 'The child sees cheap goods as good for everyone.', 'Offer "They cannot" next to the right answer and ask the question again in a new context.', 'Compare a local shoemaker with cheap imported shoes.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.POLITI.CITIZENSHIP.CZ_CITIZEN.M_CZ_GLOBAL_TRAVEL', 'SOCI.G7.POLITI.CITIZENSHIP.CZ_CITIZEN', 'Thinks you must travel abroad to act as a global citizen.', '{"question":"How can a learner in Kenya act as a global citizen without travelling?","wrong_answer":"They cannot","correct_answer":"By caring for the environment and respecting other cultures"}'::jsonb, 'Global sounds far away.', 'Offer "They cannot" next to the right answer and ask the question again in a new context.', 'List global actions done at home.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G7.POLITI.CITIZENSHIP.CZ_CITIZEN.M_CZ_KENYAN_GOODS', 'SOCI.G7.POLITI.CITIZENSHIP.CZ_CITIZEN', 'Does not see buying Kenyan goods as loyal to Kenya.', '{"question":"How does buying Kenyan-made goods show loyalty to Kenya?","wrong_answer":"It does not","correct_answer":"It supports local jobs and industries"}'::jsonb, 'The child thinks only of price.', 'Offer "It does not" next to the right answer and ask the question again in a new context.', 'Trace the money from buying a Kenyan product.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
